window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[16]={"1600":{"example:1600:exzh":"This road is very narrow.","example:1600:exzh2":"There are trees on both sides of the road.","example:1600:exzh3":"Look carefully both ways when you cross the road.","example:1600:exzh4":"The road is crowded with traffic.","example:1600:exzh5":"If you go straight along this road, you'll reach the station.","grammar:1600:ex:trans":"This road is very narrow.","grammar:1600:ex:structure":"〜はとても狭いです","grammar:1600:ex:explain":"This is an i-adjective predicate sentence, 「〜はとても狭いです」. 「この道路は」 uses 「は」 to present the topic, 「とても」 is a degree adverb = very, and 「狭い」 is an i-adjective as the predicate with 「です」 added = is narrow. 「道路（どうろ）」 means road or street and is fairly formal; in casual speech 「道（みち）」 is more common. The whole sentence 「この道路はとても狭いです」 means 'this road is very narrow.'","grammar:1600:ex:words:0:zh":"this","grammar:1600:ex:words:0:pos":"pre-noun adjectival","grammar:1600:ex:words:1:zh":"road","grammar:1600:ex:words:1:note":"どうろ","grammar:1600:ex:words:1:pos":"noun","grammar:1600:ex:words:2:zh":"(topic)","grammar:1600:ex:words:2:pos":"particle","grammar:1600:ex:words:3:zh":"extremely","grammar:1600:ex:words:3:pos":"adverb","grammar:1600:ex:words:4:zh":"narrow, cramped","grammar:1600:ex:words:4:note":"せまい","grammar:1600:ex:words:4:pos":"adjective","grammar:1600:ex:words:5:zh":"(polite form)","grammar:1600:ex:words:5:pos":"copula","grammar:1600:ex:points:0":"❗道路（どうろ）: road, street (fairly formal; in casual speech people often say 「道（みち）」).","grammar:1600:ex:points:1":"道路: road.","grammar:1600:ex2:trans":"There are trees on both sides of the road.","grammar:1600:ex2:structure":"〜の両側に〜があります","grammar:1600:ex2:words:0:zh":"road","grammar:1600:ex2:words:0:note":"どうろ","grammar:1600:ex2:words:0:pos":"noun","grammar:1600:ex2:words:1:zh":"'s","grammar:1600:ex2:words:1:pos":"particle","grammar:1600:ex2:words:2:zh":"both sides","grammar:1600:ex2:words:2:note":"りょうがわ","grammar:1600:ex2:words:2:pos":"noun","grammar:1600:ex2:words:3:zh":"(location of existence)","grammar:1600:ex2:words:3:pos":"particle","grammar:1600:ex2:words:4:zh":"tree","grammar:1600:ex2:words:4:note":"き","grammar:1600:ex2:words:4:pos":"noun","grammar:1600:ex2:words:5:zh":"(nominative)","grammar:1600:ex2:words:5:pos":"particle","grammar:1600:ex2:words:6:zh":"there is / are","grammar:1600:ex2:words:6:pos":"verb","grammar:1600:ex2:points:0":"❗両側: both sides (両 + 側); 道路の両側 = both sides of the road.","grammar:1600:ex2:points:1":"両側: both sides.","grammar:1600:ex3:trans":"When you cross the road, look carefully both ways.","grammar:1600:ex3:structure":"道路を渡るときは〜てください","grammar:1600:ex3:words:0:zh":"road, street","grammar:1600:ex3:words:0:note":"どうろ","grammar:1600:ex3:words:0:pos":"noun","grammar:1600:ex3:words:1:zh":"(the place passed through)","grammar:1600:ex3:words:1:pos":"particle","grammar:1600:ex3:words:2:zh":"cross","grammar:1600:ex3:words:2:note":"わたる","grammar:1600:ex3:words:2:pos":"verb","grammar:1600:ex3:words:3:zh":"time","grammar:1600:ex3:words:3:pos":"noun","grammar:1600:ex3:words:4:zh":"(topic)","grammar:1600:ex3:words:4:pos":"particle","grammar:1600:ex3:words:5:zh":"left and right","grammar:1600:ex3:words:5:note":"さゆう","grammar:1600:ex3:words:5:pos":"noun","grammar:1600:ex3:words:6:zh":"(object marker)","grammar:1600:ex3:words:6:pos":"particle","grammar:1600:ex3:words:7:zh":"carefully","grammar:1600:ex3:words:7:pos":"adverb","grammar:1600:ex3:words:8:zh":"look","grammar:1600:ex3:words:8:note":"みて; the te-form of 見る","grammar:1600:ex3:words:8:pos":"verb","grammar:1600:ex3:words:9:zh":"please","grammar:1600:ex3:words:9:pos":"auxiliary verb","grammar:1600:ex3:points:0":"❗道路を渡る: to cross the road. 「道路」 is a road for vehicles, and the place being crossed takes 「を」.","grammar:1600:ex3:points:1":"「〜るときは」: dictionary form of a verb + とき, meaning 'when you do …'.","grammar:1600:ex3:points:2":"「見てください」: te-form + ください, meaning 'please do …'.","grammar:1600:ex4:trans":"The road is crowded with traffic.","grammar:1600:ex4:structure":"〜は〜で混雑しています","grammar:1600:ex4:words:0:zh":"road","grammar:1600:ex4:words:0:note":"どうろ","grammar:1600:ex4:words:0:pos":"noun","grammar:1600:ex4:words:1:zh":"(topic)","grammar:1600:ex4:words:1:pos":"particle","grammar:1600:ex4:words:2:zh":"transportation","grammar:1600:ex4:words:2:note":"こうつう","grammar:1600:ex4:words:2:pos":"noun","grammar:1600:ex4:words:3:zh":"(cause)","grammar:1600:ex4:words:3:pos":"particle","grammar:1600:ex4:words:4:zh":"crowded","grammar:1600:ex4:words:4:note":"こんざつしています","grammar:1600:ex4:words:4:pos":"verb","grammar:1600:ex4:points:0":"❗混雑する: to be crowded, to be jammed; 交通で混雑 = congested with traffic.","grammar:1600:ex4:points:1":"混雑する: to be crowded.","grammar:1600:ex5:trans":"If you go straight along this road, you reach the station.","grammar:1600:ex5:structure":"〜をまっすぐ行くと〜です","grammar:1600:ex5:words:0:zh":"this","grammar:1600:ex5:words:0:pos":"pre-noun adjectival","grammar:1600:ex5:words:1:zh":"road","grammar:1600:ex5:words:1:note":"どうろ","grammar:1600:ex5:words:1:pos":"noun","grammar:1600:ex5:words:2:zh":"(path)","grammar:1600:ex5:words:2:pos":"particle","grammar:1600:ex5:words:3:zh":"straight","grammar:1600:ex5:words:3:pos":"adverb","grammar:1600:ex5:words:4:zh":"walk","grammar:1600:ex5:words:4:note":"いく","grammar:1600:ex5:words:4:pos":"verb","grammar:1600:ex5:words:5:zh":"(as soon as…)","grammar:1600:ex5:words:5:pos":"particle","grammar:1600:ex5:words:6:zh":"station","grammar:1600:ex5:words:6:note":"えき","grammar:1600:ex5:words:6:pos":"noun","grammar:1600:ex5:words:7:zh":"is","grammar:1600:ex5:words:7:pos":"copula","grammar:1600:ex5:points:0":"❗〜を行く: to go along … (を for a route); まっすぐ行くと = if you go straight, …","grammar:1600:ex5:points:1":"まっすぐ行く: to go straight."},"1601":{"example:1601:exzh":"I'm going to the supermarket to buy food.","example:1601:exzh2":"I'm looking for fresh vegetables at the grocery store.","example:1601:exzh3":"Let me know if we run out of food.","example:1601:exzh4":"He donated food.","example:1601:exzh5":"Food prices are rising."},"1602":{"example:1602:exzh":"Thanks for your help!","example:1602:exzh2":"Thank you, you really saved me.","example:1602:exzh3":"It's important to say thank you.","example:1602:exzh4":"He always says thank you.","example:1602:exzh5":"I'll write a letter to say thank you.","grammar:1602:ex:trans":"Thanks for your help!","grammar:1602:ex:structure":"〜てくれて有難う","grammar:1602:ex:explain":"The key point of this sentence is the gratitude pattern 「〜てくれてありがとう」. The verb 「手伝う」 first becomes the te-form 「手伝って」, then attaches to the te-form 「くれて」 of the auxiliary verb 「くれる」, showing that the other person did this action for me and carrying a sense of receiving a favor; finally the interjection 「有難う（ありがとう）」 expresses thanks. The whole sentence means 'thanks for helping me,' and it makes clear which action you are thanking someone for, more so than just saying 「ありがとう」. 「有難う」 is the kanji spelling, and in everyday writing it is usually in hiragana.","grammar:1602:ex:words:0:zh":"help","grammar:1602:ex:words:0:note":"てつだって","grammar:1602:ex:words:0:pos":"verb","grammar:1602:ex:words:1:zh":"makes (for me)","grammar:1602:ex:words:1:pos":"auxiliary verb","grammar:1602:ex:words:2:zh":"thank you","grammar:1602:ex:words:2:note":"ありがとう","grammar:1602:ex:words:2:pos":"interjection","grammar:1602:ex:points:0":"❗有難う（ありがとう）: thank you (kanji spelling; usually written in hiragana); 〜てくれてありがとう = thanks for …-ing for me.","grammar:1602:ex:points:1":"有難う: thank you.","grammar:1602:ex2:trans":"Thank you — thanks to you, I got help.","grammar:1602:ex2:structure":"有難う、〜のおかげで助かりました","grammar:1602:ex2:words:0:zh":"thank you","grammar:1602:ex2:words:0:note":"ありがとう","grammar:1602:ex2:words:0:pos":"interjection","grammar:1602:ex2:words:1:zh":"you","grammar:1602:ex2:words:1:pos":"pronoun","grammar:1602:ex2:words:2:zh":"'s","grammar:1602:ex2:words:2:pos":"particle","grammar:1602:ex2:words:3:zh":"thanks to","grammar:1602:ex2:words:3:pos":"set phrase","grammar:1602:ex2:words:4:zh":"was helped","grammar:1602:ex2:words:4:note":"たすかりました","grammar:1602:ex2:words:4:pos":"verb","grammar:1602:ex2:points:0":"❗〜のおかげで: thanks to …; 助かる = to be saved, to be a big help.","grammar:1602:ex2:points:1":"おかげで: thanks to.","grammar:1602:ex3:trans":"Saying thank you is important.","grammar:1602:ex3:structure":"有難うと言うのは大切です","grammar:1602:ex3:words:0:zh":"thank you","grammar:1602:ex3:words:0:note":"ありがとう","grammar:1602:ex3:words:0:pos":"interjection","grammar:1602:ex3:words:1:zh":"(quotation)","grammar:1602:ex3:words:1:pos":"particle","grammar:1602:ex3:words:2:zh":"tell","grammar:1602:ex3:words:2:note":"いう","grammar:1602:ex3:words:2:pos":"verb","grammar:1602:ex3:words:3:zh":"(nominalizer)","grammar:1602:ex3:words:3:pos":"particle","grammar:1602:ex3:words:4:zh":"(topic)","grammar:1602:ex3:words:4:pos":"particle","grammar:1602:ex3:words:5:zh":"important","grammar:1602:ex3:words:5:note":"たいせつ","grammar:1602:ex3:words:5:pos":"na-adjective","grammar:1602:ex3:words:6:zh":"(polite form)","grammar:1602:ex3:words:6:pos":"copula","grammar:1602:ex3:points:0":"❗〜と言う: to say …; 有難うと言う = to say thank you.","grammar:1602:ex3:points:1":"有難うと言う: to say thank you.","grammar:1602:ex4:trans":"He always says thank you.","grammar:1602:ex4:structure":"いつも有難うと言います","grammar:1602:ex4:words:0:zh":"he","grammar:1602:ex4:words:0:note":"かれ","grammar:1602:ex4:words:0:pos":"pronoun","grammar:1602:ex4:words:1:zh":"(topic)","grammar:1602:ex4:words:1:pos":"particle","grammar:1602:ex4:words:2:zh":"always","grammar:1602:ex4:words:2:pos":"adverb","grammar:1602:ex4:words:3:zh":"thank you","grammar:1602:ex4:words:3:note":"ありがとう","grammar:1602:ex4:words:3:pos":"interjection","grammar:1602:ex4:words:4:zh":"(quotation)","grammar:1602:ex4:words:4:pos":"particle","grammar:1602:ex4:words:5:zh":"tell","grammar:1602:ex4:words:5:note":"いいます","grammar:1602:ex4:words:5:pos":"verb","grammar:1602:ex4:points:0":"❗いつも〜と言う: always says …; the polite 「ありがとうございます」 is more formal.","grammar:1602:ex4:points:1":"いつも有難う: always says thanks.","grammar:1602:ex5:trans":"I'll write a letter to express my thanks.","grammar:1602:ex5:structure":"手紙を書いて有難うを伝えます","grammar:1602:ex5:words:0:zh":"letter","grammar:1602:ex5:words:0:note":"てがみ","grammar:1602:ex5:words:0:pos":"noun","grammar:1602:ex5:words:1:zh":"(object marker)","grammar:1602:ex5:words:1:pos":"particle","grammar:1602:ex5:words:2:zh":"write","grammar:1602:ex5:words:2:note":"かいて","grammar:1602:ex5:words:2:pos":"verb","grammar:1602:ex5:words:3:zh":"thanks","grammar:1602:ex5:words:3:note":"ありがとう","grammar:1602:ex5:words:3:pos":"interjection","grammar:1602:ex5:words:4:zh":"(object marker)","grammar:1602:ex5:words:4:pos":"particle","grammar:1602:ex5:words:5:zh":"express","grammar:1602:ex5:words:5:note":"つたえます","grammar:1602:ex5:words:5:pos":"verb","grammar:1602:ex5:points:0":"❗〜を伝える: to convey …; 有難うを伝える = to express thanks.","grammar:1602:ex5:points:1":"有難うを伝える: to give thanks.","exam:1602:zh":"My friend carried my heavy luggage for me, so I said thank you.","exam:1602:why":"「ありがとう」 is used to thank someone for their help. 「いただきます」 is said before starting a meal."},"1603":{"example:1603:exzh":"Let's decide when to travel.","example:1603:exzh2":"There's a lot of rain at that time of year.","example:1603:exzh3":"There are many tourists at this time of year.","example:1603:exzh4":"The food varies depending on the time of year.","example:1603:exzh5":"The festival season is very lively."},"1604":{"example:1604:exzh":"I went camping with friends.","example:1604:exzh2":"Camping is a fun activity.","example:1604:exzh3":"Please help me prepare for the camping trip.","example:1604:exzh4":"We're going camping this weekend.","example:1604:exzh5":"The campfire has started.","grammar:1604:ex:trans":"I went camping with friends.","grammar:1604:ex:structure":"〜とキャンプに行きました","grammar:1604:ex:explain":"This sentence has two key particles. 「と」 follows 「友達」 and marks the person you do the action together with, i.e. 'together with a friend'; 「に」 follows 「キャンプ」 and marks the purpose of the movement, so 「キャンプに行く」 means 'to go camping' — this 'action noun + に + 行く' pattern is a set way to say 'go do something.' The verb 「行く」 is in the polite past form 「行きました」, showing the trip has already happened.","grammar:1604:ex:words:0:zh":"friend","grammar:1604:ex:words:0:note":"ともだち","grammar:1604:ex:words:0:pos":"noun","grammar:1604:ex:words:1:zh":"(object)","grammar:1604:ex:words:1:pos":"particle","grammar:1604:ex:words:2:zh":"camping","grammar:1604:ex:words:2:note":"loanword","grammar:1604:ex:words:2:pos":"noun","grammar:1604:ex:words:3:zh":"(purpose)","grammar:1604:ex:words:3:pos":"particle","grammar:1604:ex:words:4:zh":"went","grammar:1604:ex:words:4:note":"いきました","grammar:1604:ex:words:4:pos":"verb","grammar:1604:ex:points:0":"❗キャンプ: camping (camp); キャンプに行く = to go camping.","grammar:1604:ex:points:1":"キャンプ: camping.","grammar:1604:ex2:trans":"Camping is a fun activity.","grammar:1604:ex2:structure":"〜は楽しいアクティビティです","grammar:1604:ex2:words:0:zh":"camping","grammar:1604:ex2:words:0:note":"loanword","grammar:1604:ex2:words:0:pos":"noun","grammar:1604:ex2:words:1:zh":"(topic)","grammar:1604:ex2:words:1:pos":"particle","grammar:1604:ex2:words:2:zh":"interesting","grammar:1604:ex2:words:2:note":"たのしい","grammar:1604:ex2:words:2:pos":"adjective","grammar:1604:ex2:words:3:zh":"event","grammar:1604:ex2:words:3:note":"loanword","grammar:1604:ex2:words:3:pos":"noun","grammar:1604:ex2:words:4:zh":"is","grammar:1604:ex2:words:4:pos":"copula","grammar:1604:ex2:points:0":"❗アクティビティ: activity (activity); 楽しい = fun.","grammar:1604:ex2:points:1":"楽しいアクティビティ: a fun activity.","grammar:1604:ex3:trans":"Please help me get ready for the camping trip.","grammar:1604:ex3:structure":"〜の準備を手伝ってください","grammar:1604:ex3:words:0:zh":"camping","grammar:1604:ex3:words:0:note":"loanword","grammar:1604:ex3:words:0:pos":"noun","grammar:1604:ex3:words:1:zh":"'s","grammar:1604:ex3:words:1:pos":"particle","grammar:1604:ex3:words:2:zh":"prepare","grammar:1604:ex3:words:2:note":"じゅんび","grammar:1604:ex3:words:2:pos":"noun","grammar:1604:ex3:words:3:zh":"(object marker)","grammar:1604:ex3:words:3:pos":"particle","grammar:1604:ex3:words:4:zh":"help","grammar:1604:ex3:words:4:note":"てつだって","grammar:1604:ex3:words:4:pos":"verb","grammar:1604:ex3:words:5:zh":"please","grammar:1604:ex3:words:5:pos":"auxiliary verb","grammar:1604:ex3:points:0":"❗キャンプの準備: camping preparations; 手伝う = to help.","grammar:1604:ex3:points:1":"準備を手伝う: to help with the preparations.","grammar:1604:ex4:trans":"We're going camping this weekend.","grammar:1604:ex4:structure":"〜にキャンプをします","grammar:1604:ex4:words:0:zh":"this","grammar:1604:ex4:words:0:pos":"pre-noun adjectival","grammar:1604:ex4:words:1:zh":"weekend","grammar:1604:ex4:words:1:note":"しゅうまつ","grammar:1604:ex4:words:1:pos":"noun","grammar:1604:ex4:words:2:zh":"(point in time)","grammar:1604:ex4:words:2:pos":"particle","grammar:1604:ex4:words:3:zh":"camping","grammar:1604:ex4:words:3:note":"loanword","grammar:1604:ex4:words:3:pos":"noun","grammar:1604:ex4:words:4:zh":"(object marker)","grammar:1604:ex4:words:4:pos":"particle","grammar:1604:ex4:words:5:zh":"do","grammar:1604:ex4:words:5:pos":"verb","grammar:1604:ex4:points:0":"❗キャンプをする: to camp; この週末に = this weekend.","grammar:1604:ex4:points:1":"キャンプをする: to camp.","grammar:1604:ex5:trans":"The campfire has started.","grammar:1604:ex5:structure":"〜が始まりました","grammar:1604:ex5:words:0:zh":"campfire","grammar:1604:ex5:words:0:note":"loanword","grammar:1604:ex5:words:0:pos":"noun","grammar:1604:ex5:words:1:zh":"(nominative)","grammar:1604:ex5:words:1:pos":"particle","grammar:1604:ex5:words:2:zh":"started","grammar:1604:ex5:words:2:note":"はじまりました","grammar:1604:ex5:words:2:pos":"verb","grammar:1604:ex5:points:0":"❗キャンプファイヤー: campfire (the standard spelling; an earlier batch showed the misspelling 「キャンプファイア」).","grammar:1604:ex5:points:1":"キャンプファイヤー: campfire."},"1605":{"example:1605:exzh":"My favorite color is green.","example:1605:exzh2":"This wall is painted green.","example:1605:exzh3":"I'm wearing green clothes.","example:1605:exzh4":"There's a lot of green in nature.","example:1605:exzh5":"The green part is very beautiful.","grammar:1605:ex:trans":"My favorite color is green.","grammar:1605:ex:structure":"〜はグリーンです","grammar:1605:ex:explain":"The subject part 「私の好きな色」 is built up layer by layer: 「私の」 means 'my,' 「好きな」 is the na-adjective 「好き」, which takes 「な」 when it comes before a noun, and the whole string modifies 「色」, meaning 'the color I like.' 「は」 presents this whole phrase as the topic, and 「グリーンです」 says that it is green. 「グリーン」 is a loanword, and the native Japanese equivalent is 「緑（みどり）」.","grammar:1605:ex:words:0:zh":"I","grammar:1605:ex:words:0:note":"わたし","grammar:1605:ex:words:0:pos":"pronoun","grammar:1605:ex:words:1:zh":"'s","grammar:1605:ex:words:1:pos":"particle","grammar:1605:ex:words:2:zh":"to like","grammar:1605:ex:words:2:note":"すき","grammar:1605:ex:words:2:pos":"na-adjective","grammar:1605:ex:words:3:zh":"(attributive form)","grammar:1605:ex:words:3:pos":"auxiliary verb","grammar:1605:ex:words:4:zh":"color","grammar:1605:ex:words:4:note":"いろ","grammar:1605:ex:words:4:pos":"noun","grammar:1605:ex:words:5:zh":"(topic)","grammar:1605:ex:words:5:pos":"particle","grammar:1605:ex:words:6:zh":"green","grammar:1605:ex:words:6:note":"loanword","grammar:1605:ex:words:6:pos":"noun","grammar:1605:ex:words:7:zh":"is","grammar:1605:ex:words:7:pos":"copula","grammar:1605:ex:points:0":"❗グリーン: green (green; the native Japanese word is 「緑（みどり）」).","grammar:1605:ex:points:1":"グリーン: green.","grammar:1605:ex2:trans":"This wall is painted green.","grammar:1605:ex2:structure":"〜はグリーンに塗られています","grammar:1605:ex2:words:0:zh":"this","grammar:1605:ex2:words:0:pos":"pre-noun adjectival","grammar:1605:ex2:words:1:zh":"wall","grammar:1605:ex2:words:1:note":"かべ","grammar:1605:ex2:words:1:pos":"noun","grammar:1605:ex2:words:2:zh":"(topic)","grammar:1605:ex2:words:2:pos":"particle","grammar:1605:ex2:words:3:zh":"green","grammar:1605:ex2:words:3:note":"loanword","grammar:1605:ex2:words:3:pos":"noun","grammar:1605:ex2:words:4:zh":"(result)","grammar:1605:ex2:words:4:pos":"particle","grammar:1605:ex2:words:5:zh":"is painted","grammar:1605:ex2:words:5:note":"ぬられています","grammar:1605:ex2:words:5:pos":"verb","grammar:1605:ex2:points:0":"❗〜に塗られる: to be painted … (passive of 塗る); 壁 = wall.","grammar:1605:ex2:points:1":"グリーンに塗る: to paint green.","grammar:1605:ex3:trans":"I'm wearing green clothes.","grammar:1605:ex3:structure":"〜の服を着ています","grammar:1605:ex3:words:0:zh":"green","grammar:1605:ex3:words:0:note":"loanword","grammar:1605:ex3:words:0:pos":"noun","grammar:1605:ex3:words:1:zh":"'s","grammar:1605:ex3:words:1:pos":"particle","grammar:1605:ex3:words:2:zh":"clothes","grammar:1605:ex3:words:2:note":"ふく","grammar:1605:ex3:words:2:pos":"noun","grammar:1605:ex3:words:3:zh":"(object marker)","grammar:1605:ex3:words:3:pos":"particle","grammar:1605:ex3:words:4:zh":"Wearing","grammar:1605:ex3:words:4:note":"きています","grammar:1605:ex3:words:4:pos":"verb","grammar:1605:ex3:points:0":"❗グリーンの服: green clothes; 着る＝to wear.","grammar:1605:ex3:points:1":"グリーンの服: green clothes.","grammar:1605:ex4:trans":"There's lots of green in nature.","grammar:1605:ex4:structure":"〜にはグリーンがたくさんあります","grammar:1605:ex4:words:0:zh":"nature","grammar:1605:ex4:words:0:note":"しぜん","grammar:1605:ex4:words:0:pos":"noun","grammar:1605:ex4:words:1:zh":"(location of existence)","grammar:1605:ex4:words:1:pos":"particle","grammar:1605:ex4:words:2:zh":"(contrast)","grammar:1605:ex4:words:2:pos":"particle","grammar:1605:ex4:words:3:zh":"green","grammar:1605:ex4:words:3:note":"loanword","grammar:1605:ex4:words:3:pos":"noun","grammar:1605:ex4:words:4:zh":"(nominative)","grammar:1605:ex4:words:4:pos":"particle","grammar:1605:ex4:words:5:zh":"a lot","grammar:1605:ex4:words:5:pos":"adverb","grammar:1605:ex4:words:6:zh":"there is / are","grammar:1605:ex4:words:6:pos":"verb","grammar:1605:ex4:points:0":"❗自然のグリーン: the green of nature; たくさんある＝there's plenty of it.","grammar:1605:ex4:points:1":"グリーンがたくさん: full of green.","grammar:1605:ex5:trans":"The green parts are very beautiful.","grammar:1605:ex5:structure":"〜がとても美しいです","grammar:1605:ex5:words:0:zh":"green","grammar:1605:ex5:words:0:note":"loanword","grammar:1605:ex5:words:0:pos":"noun","grammar:1605:ex5:words:1:zh":"'s","grammar:1605:ex5:words:1:pos":"particle","grammar:1605:ex5:words:2:zh":"part","grammar:1605:ex5:words:2:note":"ぶぶん","grammar:1605:ex5:words:2:pos":"noun","grammar:1605:ex5:words:3:zh":"(nominative)","grammar:1605:ex5:words:3:pos":"particle","grammar:1605:ex5:words:4:zh":"extremely","grammar:1605:ex5:words:4:pos":"adverb","grammar:1605:ex5:words:5:zh":"beautiful","grammar:1605:ex5:words:5:note":"うつくしい","grammar:1605:ex5:words:5:pos":"adjective","grammar:1605:ex5:words:6:zh":"(polite form)","grammar:1605:ex5:words:6:pos":"copula","grammar:1605:ex5:points:0":"❗グリーンの部分: the green part; 美しい＝beautiful.","grammar:1605:ex5:points:1":"グリーンの部分: the green area."},"1606":{"example:1606:exzh":"Don't forget to wear a mask when you go out.","example:1606:exzh2":"He went shopping wearing a mask.","example:1606:exzh3":"Masks are important for preventing infections.","example:1606:exzh4":"You must wear a mask in the hospital.","example:1606:exzh5":"Don't forget to take off your mask."},"1607":{"example:1607:exzh":"I'm studying chemistry at university.","example:1607:exzh2":"Chemistry is one of the interesting subjects.","example:1607:exzh3":"Chemistry experiments are a lot of fun.","example:1607:exzh4":"He is a chemistry expert.","example:1607:exzh5":"Chemistry knowledge is also useful in daily life.","grammar:1607:ex:trans":"I study chemistry at university.","grammar:1607:ex:structure":"〜で化学を勉強しています","grammar:1607:ex:explain":"Keep the two particles here clearly apart: 「で」 attaches to 「大学」 to show where the action happens (at university), while 「を」 marks 「化学」 as the object of study. The ending 「勉強しています」 is the 「〜ている」 form of 「勉強する」; it isn't simple progressive here but describes a long-term state — you're continuously studying it, i.e. it's your major. 「化学」 is read 「かがく」, the same as 「科学」, so you tell them apart by context.","grammar:1607:ex:words:0:zh":"I","grammar:1607:ex:words:0:note":"わたし","grammar:1607:ex:words:0:pos":"pronoun","grammar:1607:ex:words:1:zh":"(topic)","grammar:1607:ex:words:1:pos":"particle","grammar:1607:ex:words:2:zh":"university","grammar:1607:ex:words:2:note":"だいがく","grammar:1607:ex:words:2:pos":"noun","grammar:1607:ex:words:3:zh":"(place)","grammar:1607:ex:words:3:pos":"particle","grammar:1607:ex:words:4:zh":"chemistry","grammar:1607:ex:words:4:note":"かがく","grammar:1607:ex:words:4:pos":"noun","grammar:1607:ex:words:5:zh":"(object marker)","grammar:1607:ex:words:5:pos":"particle","grammar:1607:ex:words:6:zh":"has been studying","grammar:1607:ex:words:6:note":"べんきょうしています","grammar:1607:ex:words:6:pos":"verb","grammar:1607:ex:points:0":"❗化学（かがく）: chemistry (same pronunciation かがく as 「科学」＝science, so context tells them apart; in speech it's called 「ばけがく」 to distinguish).","grammar:1607:ex:points:1":"化学: chemistry.","grammar:1607:ex2:trans":"Chemistry is one of the interesting subjects.","grammar:1607:ex2:structure":"〜は〜科目の一つです","grammar:1607:ex2:words:0:zh":"chemistry","grammar:1607:ex2:words:0:note":"かがく","grammar:1607:ex2:words:0:pos":"noun","grammar:1607:ex2:words:1:zh":"(topic)","grammar:1607:ex2:words:1:pos":"particle","grammar:1607:ex2:words:2:zh":"interesting","grammar:1607:ex2:words:2:note":"おもしろい","grammar:1607:ex2:words:2:pos":"adjective","grammar:1607:ex2:words:3:zh":"subject","grammar:1607:ex2:words:3:note":"かもく","grammar:1607:ex2:words:3:pos":"noun","grammar:1607:ex2:words:4:zh":"'s","grammar:1607:ex2:words:4:pos":"particle","grammar:1607:ex2:words:5:zh":"one","grammar:1607:ex2:words:5:note":"ひとつ","grammar:1607:ex2:words:5:pos":"noun","grammar:1607:ex2:words:6:zh":"is","grammar:1607:ex2:words:6:pos":"copula","grammar:1607:ex2:points:0":"❗科目の一つ: one of the subjects; 面白い＝interesting.","grammar:1607:ex2:points:1":"科目の一つ: one subject.","grammar:1607:ex3:trans":"Chemistry experiments are a lot of fun.","grammar:1607:ex3:structure":"〜の実験はとても楽しいです","grammar:1607:ex3:words:0:zh":"chemistry","grammar:1607:ex3:words:0:note":"かがく","grammar:1607:ex3:words:0:pos":"noun","grammar:1607:ex3:words:1:zh":"'s","grammar:1607:ex3:words:1:pos":"particle","grammar:1607:ex3:words:2:zh":"experiment","grammar:1607:ex3:words:2:note":"じっけん","grammar:1607:ex3:words:2:pos":"noun","grammar:1607:ex3:words:3:zh":"(topic)","grammar:1607:ex3:words:3:pos":"particle","grammar:1607:ex3:words:4:zh":"extremely","grammar:1607:ex3:words:4:pos":"adverb","grammar:1607:ex3:words:5:zh":"interesting","grammar:1607:ex3:words:5:note":"たのしい","grammar:1607:ex3:words:5:pos":"adjective","grammar:1607:ex3:words:6:zh":"(polite form)","grammar:1607:ex3:words:6:pos":"copula","grammar:1607:ex3:points:0":"❗化学の実験: chemistry experiment; 実験＝experiment.","grammar:1607:ex3:points:1":"化学の実験: chemistry experiment.","grammar:1607:ex4:trans":"He is a chemistry expert.","grammar:1607:ex4:structure":"〜の専門家です","grammar:1607:ex4:words:0:zh":"he","grammar:1607:ex4:words:0:note":"かれ","grammar:1607:ex4:words:0:pos":"pronoun","grammar:1607:ex4:words:1:zh":"(topic)","grammar:1607:ex4:words:1:pos":"particle","grammar:1607:ex4:words:2:zh":"chemistry","grammar:1607:ex4:words:2:note":"かがく","grammar:1607:ex4:words:2:pos":"noun","grammar:1607:ex4:words:3:zh":"'s","grammar:1607:ex4:words:3:pos":"particle","grammar:1607:ex4:words:4:zh":"expert","grammar:1607:ex4:words:4:note":"せんもんか","grammar:1607:ex4:words:4:pos":"noun","grammar:1607:ex4:words:5:zh":"is","grammar:1607:ex4:words:5:pos":"copula","grammar:1607:ex4:points:0":"❗化学の専門家: chemistry expert.","grammar:1607:ex4:points:1":"専門家: expert.","grammar:1607:ex5:trans":"Chemistry knowledge is useful in everyday life too.","grammar:1607:ex5:structure":"〜にも役立ちます","grammar:1607:ex5:words:0:zh":"chemistry","grammar:1607:ex5:words:0:note":"かがく","grammar:1607:ex5:words:0:pos":"noun","grammar:1607:ex5:words:1:zh":"'s","grammar:1607:ex5:words:1:pos":"particle","grammar:1607:ex5:words:2:zh":"knowledge","grammar:1607:ex5:words:2:note":"ちしき","grammar:1607:ex5:words:2:pos":"noun","grammar:1607:ex5:words:3:zh":"(topic)","grammar:1607:ex5:words:3:pos":"particle","grammar:1607:ex5:words:4:zh":"everyday life","grammar:1607:ex5:words:4:note":"にちじょうせいかつ","grammar:1607:ex5:words:4:pos":"noun","grammar:1607:ex5:words:5:zh":"(object)","grammar:1607:ex5:words:5:pos":"particle","grammar:1607:ex5:words:6:zh":"also, too","grammar:1607:ex5:words:6:pos":"particle","grammar:1607:ex5:words:7:zh":"helpful","grammar:1607:ex5:words:7:note":"やくだちます","grammar:1607:ex5:words:7:pos":"verb","grammar:1607:ex5:points:0":"❗〜に役立つ: to be useful for …; 日常生活にも＝in daily life too.","grammar:1607:ex5:points:1":"役立つ: to be useful."},"1608":{"example:1608:exzh":"I put film in the camera.","example:1608:exzh2":"This film is made of a special material.","example:1608:exzh3":"Don't forget to change the film.","example:1608:exzh4":"The new film has been released.","example:1608:exzh5":"Use film to edit images."},"1609":{"example:1609:exzh":"Maintaining the environment is very important.","example:1609:exzh2":"He exercises to maintain his health.","example:1609:exzh3":"Maintaining public order is difficult.","example:1609:exzh4":"We're working hard to maintain the new system.","example:1609:exzh5":"Proper maintenance is needed."},"1610":{"example:1610:exzh":"This substance dissolves in water.","example:1610:exzh2":"In science, we study the properties of substances.","example:1610:exzh3":"Learning about how substances change is fun.","example:1610:exzh4":"Preserving substances is important.","example:1610:exzh5":"This substance is harmful to the human body."},"1611":{"example:1611:exzh":"He hurt his butt.","example:1611:exzh2":"The child bumped their butt on the ground.","example:1611:exzh3":"Running with your butt tightened makes you less tired.","example:1611:exzh4":"My butt hurt, so I avoided sitting down.","example:1611:exzh5":"Be careful not to let your butt get cold, okay?"},"1612":{"example:1612:exzh":"Lee is my friend.","example:1612:exzh2":"Her name is Lee.","example:1612:exzh3":"Lee built a new house.","example:1612:exzh4":"I went to see a movie with Lee.","example:1612:exzh5":"We celebrate Lee's birthday."},"1613":{"example:1613:exzh":"There is one horse.","example:1613:exzh2":"I have two dogs.","example:1613:exzh3":"Three cats are playing in the park.","example:1613:exzh4":"There are five chickens at home.","example:1613:exzh5":"There are four fish in the tank.","grammar:1613:ex:trans":"There is one horse.","grammar:1613:ex:structure":"〜が一匹います","grammar:1613:ex:explain":"The focus here is the counter 「匹（ひき）」, used for small animals. Its reading changes: one is 「いっぴき」, three is 「さんびき」, so watch out for the different pronunciations. Counters usually come right before the verb without a particle. 「が」 marks the thing that exists, 「馬」, and the verb is 「います」 because a horse is alive (for inanimate things you use 「あります」). For large animals like horses, the counter 「頭（とう）」 is also common.","grammar:1613:ex:words:0:zh":"horse","grammar:1613:ex:words:0:note":"うま","grammar:1613:ex:words:0:pos":"noun","grammar:1613:ex:words:1:zh":"(nominative)","grammar:1613:ex:words:1:pos":"particle","grammar:1613:ex:words:2:zh":"one (animal)","grammar:1613:ex:words:2:note":"いっぴき","grammar:1613:ex:words:2:pos":"numeral with counter","grammar:1613:ex:words:3:zh":"there is / are","grammar:1613:ex:words:3:pos":"verb","grammar:1613:ex:points:0":"❗匹（ひき）: a counter for small animals; sound changes: 1匹＝いっぴき, 2匹＝にひき, 3匹＝さんびき (for large animals like horses 「頭（とう）」 is often used, though 一匹の馬 is also fine).","grammar:1613:ex:points:1":"匹: (animal) counter.","grammar:1613:ex2:trans":"I have two dogs.","grammar:1613:ex2:structure":"犬は二匹飼っています","grammar:1613:ex2:words:0:zh":"dog","grammar:1613:ex2:words:0:note":"いぬ","grammar:1613:ex2:words:0:pos":"noun","grammar:1613:ex2:words:1:zh":"(topic)","grammar:1613:ex2:words:1:pos":"particle","grammar:1613:ex2:words:2:zh":"two (animals)","grammar:1613:ex2:words:2:note":"にひき","grammar:1613:ex2:words:2:pos":"numeral with counter","grammar:1613:ex2:words:3:zh":"keeps","grammar:1613:ex2:words:3:note":"かっています","grammar:1613:ex2:words:3:pos":"verb","grammar:1613:ex2:points:0":"❗二匹（にひき）: two animals; 飼う＝to keep (a pet).","grammar:1613:ex2:points:1":"二匹: two animals.","grammar:1613:ex3:trans":"Three cats are playing in the park.","grammar:1613:ex3:structure":"〜が三匹遊んでいます","grammar:1613:ex3:words:0:zh":"park","grammar:1613:ex3:words:0:note":"こうえん","grammar:1613:ex3:words:0:pos":"noun","grammar:1613:ex3:words:1:zh":"(place)","grammar:1613:ex3:words:1:pos":"particle","grammar:1613:ex3:words:2:zh":"cat","grammar:1613:ex3:words:2:note":"ねこ","grammar:1613:ex3:words:2:pos":"noun","grammar:1613:ex3:words:3:zh":"(nominative)","grammar:1613:ex3:words:3:pos":"particle","grammar:1613:ex3:words:4:zh":"three (animals)","grammar:1613:ex3:words:4:note":"さんびき","grammar:1613:ex3:words:4:pos":"numeral with counter","grammar:1613:ex3:words:5:zh":"are playing","grammar:1613:ex3:words:5:note":"あそんでいます","grammar:1613:ex3:words:5:pos":"verb","grammar:1613:ex3:points:0":"❗三匹（さんびき）: three animals (the び sound change); ❓公園で＝in the park (で for place).","grammar:1613:ex3:points:1":"三匹: three animals.","grammar:1613:ex4:trans":"There are five chickens at home.","grammar:1613:ex4:structure":"〜に〜が五匹います","grammar:1613:ex4:words:0:zh":"house","grammar:1613:ex4:words:0:note":"いえ","grammar:1613:ex4:words:0:pos":"noun","grammar:1613:ex4:words:1:zh":"(location of existence)","grammar:1613:ex4:words:1:pos":"particle","grammar:1613:ex4:words:2:zh":"(contrast)","grammar:1613:ex4:words:2:pos":"particle","grammar:1613:ex4:words:3:zh":"chicken","grammar:1613:ex4:words:3:note":"にわとり","grammar:1613:ex4:words:3:pos":"noun","grammar:1613:ex4:words:4:zh":"(nominative)","grammar:1613:ex4:words:4:pos":"particle","grammar:1613:ex4:words:5:zh":"five (animals)","grammar:1613:ex4:words:5:note":"ごひき","grammar:1613:ex4:words:5:pos":"numeral with counter","grammar:1613:ex4:words:6:zh":"there is / are","grammar:1613:ex4:words:6:pos":"verb","grammar:1613:ex4:points:0":"❗五匹（ごひき）: five animals (for birds the formal counter is 「羽（わ）」, though 「匹」 also appears in casual speech).","grammar:1613:ex4:points:1":"五匹: five animals.","grammar:1613:ex5:trans":"There are four fish in the tank.","grammar:1613:ex5:structure":"〔place〕に＋〔animal〕が＋〔counter〕＋います","grammar:1613:ex5:words:0:zh":"fish tank","grammar:1613:ex5:words:0:note":"すいそう; a container for keeping fish","grammar:1613:ex5:words:0:pos":"noun","grammar:1613:ex5:words:1:zh":"exist","grammar:1613:ex5:words:1:pos":"particle","grammar:1613:ex5:words:2:zh":"fish","grammar:1613:ex5:words:2:note":"さかな: fish","grammar:1613:ex5:words:2:pos":"noun","grammar:1613:ex5:words:3:zh":"subject marker","grammar:1613:ex5:words:3:pos":"particle","grammar:1613:ex5:words:4:zh":"four (fish); four animals","grammar:1613:ex5:words:4:note":"よんひき; the count for small animals","grammar:1613:ex5:words:4:pos":"numeral with counter","grammar:1613:ex5:words:5:zh":"there is; to be","grammar:1613:ex5:words:5:pos":"verb","grammar:1613:ex5:points:0":"「四匹」 uses 「匹」 to count small animals such as fish, cats and dogs.","grammar:1613:ex5:points:1":"In 「水槽に魚がいます」, 「に」 shows the place where something exists.","exam:1613:zh":"We have two cats at home.","exam:1613:why":"Small animals like cats are counted with 「匹」. 「台」 is used for vehicles or machines, so it can't count cats."},"1614":{"example:1614:exzh":"I bought a new hat.","example:1614:exzh2":"In winter I wear a warm hat.","example:1614:exzh3":"He is always wearing a stylish hat.","example:1614:exzh4":"The hat was blown away by the wind.","example:1614:exzh5":"This hat is my favorite.","grammar:1614:ex:trans":"I bought a new hat.","grammar:1614:ex:structure":"〜を買いました","grammar:1614:ex:explain":"「新しい」 is an i-adjective and attaches directly to the noun 「帽子」 without changing form, so 新しい帽子 means a new hat. 「を」 marks 「帽子」 as the object of 「買う」, and 「買いました」 is the polite past form, meaning bought. One more thing: the verb for wearing a hat is 「かぶる」, not 「つける」 or 「着る」 — a common point of confusion.","grammar:1614:ex:words:0:zh":"I","grammar:1614:ex:words:0:note":"わたし","grammar:1614:ex:words:0:pos":"pronoun","grammar:1614:ex:words:1:zh":"(topic)","grammar:1614:ex:words:1:pos":"particle","grammar:1614:ex:words:2:zh":"new","grammar:1614:ex:words:2:note":"あたらしい","grammar:1614:ex:words:2:pos":"adjective","grammar:1614:ex:words:3:zh":"hat","grammar:1614:ex:words:3:note":"ぼうし","grammar:1614:ex:words:3:pos":"noun","grammar:1614:ex:words:4:zh":"(object marker)","grammar:1614:ex:words:4:pos":"particle","grammar:1614:ex:words:5:zh":"bought","grammar:1614:ex:words:5:note":"かいました","grammar:1614:ex:words:5:pos":"verb","grammar:1614:ex:points:0":"❗帽子（ぼうし）: hat; 帽子をかぶる＝to wear a hat (the verb is 「かぶる」).","grammar:1614:ex:points:1":"帽子: hat.","grammar:1614:ex2:trans":"In winter I wear a warm hat.","grammar:1614:ex2:structure":"〜を かぶります","grammar:1614:ex2:words:0:zh":"winter","grammar:1614:ex2:words:0:note":"ふゆ","grammar:1614:ex2:words:0:pos":"noun","grammar:1614:ex2:words:1:zh":"(point in time)","grammar:1614:ex2:words:1:pos":"particle","grammar:1614:ex2:words:2:zh":"warm","grammar:1614:ex2:words:2:note":"あたたかい","grammar:1614:ex2:words:2:pos":"adjective","grammar:1614:ex2:words:3:zh":"hat","grammar:1614:ex2:words:3:note":"ぼうし","grammar:1614:ex2:words:3:pos":"noun","grammar:1614:ex2:words:4:zh":"(object marker)","grammar:1614:ex2:words:4:pos":"particle","grammar:1614:ex2:words:5:zh":"put on","grammar:1614:ex2:words:5:note":"かぶります","grammar:1614:ex2:words:5:pos":"verb","grammar:1614:ex2:points:0":"❗帽子をかぶる: to wear a hat (かぶる＝to put on one's head); 暖かい＝warm.","grammar:1614:ex2:points:1":"帽子をかぶる: to wear a hat.","grammar:1614:ex3:trans":"He always wears a stylish hat.","grammar:1614:ex3:structure":"おしゃれな〜をかぶっています","grammar:1614:ex3:words:0:zh":"he","grammar:1614:ex3:words:0:note":"かれ","grammar:1614:ex3:words:0:pos":"pronoun","grammar:1614:ex3:words:1:zh":"(topic)","grammar:1614:ex3:words:1:pos":"particle","grammar:1614:ex3:words:2:zh":"always","grammar:1614:ex3:words:2:pos":"adverb","grammar:1614:ex3:words:3:zh":"stylish","grammar:1614:ex3:words:3:note":"おしゃれ","grammar:1614:ex3:words:3:pos":"na-adjective","grammar:1614:ex3:words:4:zh":"(attributive form)","grammar:1614:ex3:words:4:pos":"auxiliary verb","grammar:1614:ex3:words:5:zh":"hat","grammar:1614:ex3:words:5:note":"ぼうし","grammar:1614:ex3:words:5:pos":"noun","grammar:1614:ex3:words:6:zh":"(object marker)","grammar:1614:ex3:words:6:pos":"particle","grammar:1614:ex3:words:7:zh":"is wearing","grammar:1614:ex3:words:7:note":"かぶっています","grammar:1614:ex3:words:7:pos":"verb","grammar:1614:ex3:points:0":"❗おしゃれな帽子: a stylish hat; おしゃれ＝fashionable.","grammar:1614:ex3:points:1":"おしゃれな帽子: a stylish hat.","grammar:1614:ex4:trans":"The hat was blown away by the wind.","grammar:1614:ex4:structure":"〜が風で飛ばされました","grammar:1614:ex4:words:0:zh":"hat","grammar:1614:ex4:words:0:note":"ぼうし","grammar:1614:ex4:words:0:pos":"noun","grammar:1614:ex4:words:1:zh":"(nominative)","grammar:1614:ex4:words:1:pos":"particle","grammar:1614:ex4:words:2:zh":"wind","grammar:1614:ex4:words:2:note":"かぜ","grammar:1614:ex4:words:2:pos":"noun","grammar:1614:ex4:words:3:zh":"(cause)","grammar:1614:ex4:words:3:pos":"particle","grammar:1614:ex4:words:4:zh":"was blown away","grammar:1614:ex4:words:4:note":"とばされました","grammar:1614:ex4:words:4:pos":"verb","grammar:1614:ex4:points:0":"❗飛ばされる: to be blown away (the passive form of 飛ばす); 〜で＝because of … (風で＝by the wind).","grammar:1614:ex4:points:1":"風で飛ばされる: to be blown away by the wind.","grammar:1614:ex5:trans":"This hat is my favorite.","grammar:1614:ex5:structure":"〜は私のお気に入りです","grammar:1614:ex5:words:0:zh":"this","grammar:1614:ex5:words:0:pos":"pre-noun adjectival","grammar:1614:ex5:words:1:zh":"hat","grammar:1614:ex5:words:1:note":"ぼうし","grammar:1614:ex5:words:1:pos":"noun","grammar:1614:ex5:words:2:zh":"(topic)","grammar:1614:ex5:words:2:pos":"particle","grammar:1614:ex5:words:3:zh":"I","grammar:1614:ex5:words:3:note":"わたし","grammar:1614:ex5:words:3:pos":"pronoun","grammar:1614:ex5:words:4:zh":"'s","grammar:1614:ex5:words:4:pos":"particle","grammar:1614:ex5:words:5:zh":"favorite","grammar:1614:ex5:words:5:note":"おきにいり","grammar:1614:ex5:words:5:pos":"noun","grammar:1614:ex5:words:6:zh":"is","grammar:1614:ex5:words:6:pos":"copula","grammar:1614:ex5:points:0":"❗お気に入り: one's favorite thing (a set expression); この帽子＝this hat.","grammar:1614:ex5:points:1":"お気に入り: favorite.","exam:1614:zh":"The sun is strong outside, so I'll put on a hat and go out.","exam:1614:why":"A hat goes on your head and pairs with the verb かぶる. A 「シャツ」 is worn on your body, so it takes 着る."},"1615":{"example:1615:exzh":"This puzzle is easy but fun.","example:1615:exzh2":"He remains a mystery.","example:1615:exzh3":"I like solving puzzles.","example:1615:exzh4":"This book is full of mysteries.","example:1615:exzh5":"A mysterious figure appeared."},"1616":{"example:1616:exzh":"I went for a drive with a friend over the weekend.","example:1616:exzh2":"This road is perfect for a drive.","example:1616:exzh3":"I like listening to music while driving.","example:1616:exzh4":"I want to drive somewhere far away.","example:1616:exzh5":"He enjoys driving every day.","grammar:1616:ex:trans":"I went for a drive with a friend over the weekend.","grammar:1616:ex:structure":"〜とドライブに行きました","grammar:1616:ex:explain":"Each particle here does its own job: 「に」 after 「週末」 marks the point in time (on the weekend); 「と」 after 「友達」 marks who you went with; the second 「に」 after 「ドライブ」 marks the purpose of going, so 「ドライブに行く」＝to go for a drive. This 「action noun＋に＋行く」 is a fixed pattern meaning to go and do something. 「ドライブ」 is a loanword meaning an outing by car.","grammar:1616:ex:words:0:zh":"weekend","grammar:1616:ex:words:0:note":"しゅうまつ","grammar:1616:ex:words:0:pos":"noun","grammar:1616:ex:words:1:zh":"(point in time)","grammar:1616:ex:words:1:pos":"particle","grammar:1616:ex:words:2:zh":"friend","grammar:1616:ex:words:2:note":"ともだち","grammar:1616:ex:words:2:pos":"noun","grammar:1616:ex:words:3:zh":"(object)","grammar:1616:ex:words:3:pos":"particle","grammar:1616:ex:words:4:zh":"a drive","grammar:1616:ex:words:4:note":"loanword","grammar:1616:ex:words:4:pos":"noun","grammar:1616:ex:words:5:zh":"(purpose)","grammar:1616:ex:words:5:pos":"particle","grammar:1616:ex:words:6:zh":"went","grammar:1616:ex:words:6:note":"いきました","grammar:1616:ex:words:6:pos":"verb","grammar:1616:ex:points:0":"❗ドライブ: a drive, an outing by car (drive); ドライブに行く＝to go for a drive.","grammar:1616:ex:points:1":"ドライブ: a drive.","grammar:1616:ex2:trans":"This road is perfect for a drive.","grammar:1616:ex2:structure":"〜はドライブに最適です","grammar:1616:ex2:words:0:zh":"this","grammar:1616:ex2:words:0:pos":"pre-noun adjectival","grammar:1616:ex2:words:1:zh":"road","grammar:1616:ex2:words:1:note":"みち","grammar:1616:ex2:words:1:pos":"noun","grammar:1616:ex2:words:2:zh":"(topic)","grammar:1616:ex2:words:2:pos":"particle","grammar:1616:ex2:words:3:zh":"a drive","grammar:1616:ex2:words:3:note":"loanword","grammar:1616:ex2:words:3:pos":"noun","grammar:1616:ex2:words:4:zh":"(object)","grammar:1616:ex2:words:4:pos":"particle","grammar:1616:ex2:words:5:zh":"best suited for","grammar:1616:ex2:words:5:note":"さいてき","grammar:1616:ex2:words:5:pos":"na-adjective","grammar:1616:ex2:words:6:zh":"(polite form)","grammar:1616:ex2:words:6:pos":"copula","grammar:1616:ex2:points:0":"❗〜に最適: ideal for …; ドライブに最適＝perfect for a drive.","grammar:1616:ex2:points:1":"ドライブに最適: perfect for a drive.","grammar:1616:ex3:trans":"I like listening to music while I drive.","grammar:1616:ex3:structure":"ドライブ中に〜のが好きです","grammar:1616:ex3:words:0:zh":"driving","grammar:1616:ex3:words:0:note":"loanword","grammar:1616:ex3:words:0:pos":"noun","grammar:1616:ex3:words:1:zh":"inside","grammar:1616:ex3:words:1:note":"ちゅう","grammar:1616:ex3:words:1:pos":"noun","grammar:1616:ex3:words:2:zh":"(point in time)","grammar:1616:ex3:words:2:pos":"particle","grammar:1616:ex3:words:3:zh":"music","grammar:1616:ex3:words:3:note":"おんがく","grammar:1616:ex3:words:3:pos":"noun","grammar:1616:ex3:words:4:zh":"(object marker)","grammar:1616:ex3:words:4:pos":"particle","grammar:1616:ex3:words:5:zh":"listen","grammar:1616:ex3:words:5:note":"きく","grammar:1616:ex3:words:5:pos":"verb","grammar:1616:ex3:words:6:zh":"(nominalizer)","grammar:1616:ex3:words:6:pos":"particle","grammar:1616:ex3:words:7:zh":"(object)","grammar:1616:ex3:words:7:pos":"particle","grammar:1616:ex3:words:8:zh":"to like","grammar:1616:ex3:words:8:note":"すき","grammar:1616:ex3:words:8:pos":"na-adjective","grammar:1616:ex3:words:9:zh":"(polite form)","grammar:1616:ex3:words:9:pos":"copula","grammar:1616:ex3:points:0":"❗ドライブ中: in the middle of a drive (〜中＝during …).","grammar:1616:ex3:points:1":"ドライブ中: while driving.","grammar:1616:ex4:trans":"I want to go for a drive somewhere far away.","grammar:1616:ex4:structure":"遠くまでドライブしたい","grammar:1616:ex4:words:0:zh":"in the distance","grammar:1616:ex4:words:0:note":"とおく","grammar:1616:ex4:words:0:pos":"noun","grammar:1616:ex4:words:1:zh":"until","grammar:1616:ex4:words:1:pos":"particle","grammar:1616:ex4:words:2:zh":"want to go for a drive","grammar:1616:ex4:words:2:note":"ドライブしたい","grammar:1616:ex4:words:2:pos":"verb","grammar:1616:ex4:points:0":"❗遠くまで: as far as …; ドライブする＝to go for a drive; 〜たい＝to want to …","grammar:1616:ex4:points:1":"遠くまでドライブ: a drive to a faraway place.","grammar:1616:ex5:trans":"He enjoys driving every day.","grammar:1616:ex5:structure":"〜を楽しんでいます","grammar:1616:ex5:words:0:zh":"he","grammar:1616:ex5:words:0:note":"かれ","grammar:1616:ex5:words:0:pos":"pronoun","grammar:1616:ex5:words:1:zh":"(topic)","grammar:1616:ex5:words:1:pos":"particle","grammar:1616:ex5:words:2:zh":"every day","grammar:1616:ex5:words:2:note":"まいにち","grammar:1616:ex5:words:2:pos":"adverb","grammar:1616:ex5:words:3:zh":"driving","grammar:1616:ex5:words:3:note":"loanword","grammar:1616:ex5:words:3:pos":"noun","grammar:1616:ex5:words:4:zh":"(object marker)","grammar:1616:ex5:words:4:pos":"particle","grammar:1616:ex5:words:5:zh":"enjoying","grammar:1616:ex5:words:5:note":"たのしんでいます","grammar:1616:ex5:words:5:pos":"verb","grammar:1616:ex5:points:0":"❗ドライブを楽しむ: enjoy a drive.","grammar:1616:ex5:points:1":"ドライブを楽しむ: enjoy a drive."},"1617":{"example:1617:exzh":"He is a famous doctor.","example:1617:exzh2":"I need to have a doctor examine me.","example:1617:exzh3":"She aims to become a doctor.","example:1617:exzh4":"Please consult a doctor.","example:1617:exzh5":"Doctors listen carefully to what patients say."},"1618":{"example:1618:exzh":"A beast lives in the forest.","example:1618:exzh2":"He has the strength of a beast.","example:1618:exzh3":"I heard the cry of a beast.","example:1618:exzh4":"Many beasts appear in this movie.","example:1618:exzh5":"There is a law that protects beasts."},"1619":{"example:1619:exzh":"I'll go across the mountain.","example:1619:exzh2":"Crossing a river is hard.","example:1619:exzh3":"It's important to overcome obstacles.","example:1619:exzh4":"You need permission to cross the border.","example:1619:exzh5":"Once you cross this mountain pass, you can see the sea."},"1620":{"example:1620:exzh":"This statue is huge.","example:1620:exzh2":"A huge building stands there.","example:1620:exzh3":"There is a huge fish in the sea.","example:1620:exzh4":"His dream is to achieve huge success.","example:1620:exzh5":"This insect is extremely huge."},"1621":{"example:1621:exzh":"I like that type of person.","example:1621:exzh2":"What kind of person is your type?","example:1621:exzh3":"He is an interesting type of friend.","example:1621:exzh4":"I like this type of game.","example:1621:exzh5":"Her type is a kind person.","grammar:1621:ex:trans":"I like that type of person.","grammar:1621:ex:structure":"〜のタイプの人が好きです","grammar:1621:ex:explain":"Note that the object of 「好き」 takes 「が」, not 「を」: 「〜が好きです」 is the fixed Japanese pattern for expressing likes, and here 「そのタイプの人が」 is what you like. 「その」 is the pre-noun adjectival meaning that, and 「タイプの人」 is joined with 「の」 to mean that type of person. 「は」 presents 「私」 as the topic. 「タイプ」 is a loanword meaning type.","grammar:1621:ex:words:0:zh":"I","grammar:1621:ex:words:0:note":"わたし","grammar:1621:ex:words:0:pos":"pronoun","grammar:1621:ex:words:1:zh":"(topic)","grammar:1621:ex:words:1:pos":"particle","grammar:1621:ex:words:2:zh":"that","grammar:1621:ex:words:2:pos":"pre-noun adjectival","grammar:1621:ex:words:3:zh":"type","grammar:1621:ex:words:3:note":"loanword","grammar:1621:ex:words:3:pos":"noun","grammar:1621:ex:words:4:zh":"'s","grammar:1621:ex:words:4:pos":"particle","grammar:1621:ex:words:5:zh":"person","grammar:1621:ex:words:5:note":"ひと","grammar:1621:ex:words:5:pos":"noun","grammar:1621:ex:words:6:zh":"(object)","grammar:1621:ex:words:6:pos":"particle","grammar:1621:ex:words:7:zh":"to like","grammar:1621:ex:words:7:note":"すき","grammar:1621:ex:words:7:pos":"na-adjective","grammar:1621:ex:words:8:zh":"(polite form)","grammar:1621:ex:words:8:pos":"copula","grammar:1621:ex:points:0":"❗タイプ: type, kind (type); そのタイプの人 = that type of person.","grammar:1621:ex:points:1":"タイプ: type.","grammar:1621:ex2:trans":"What kind of person is your type?","grammar:1621:ex2:structure":"〜のタイプはどんな人ですか","grammar:1621:ex2:words:0:zh":"you","grammar:1621:ex2:words:0:pos":"pronoun","grammar:1621:ex2:words:1:zh":"'s","grammar:1621:ex2:words:1:pos":"particle","grammar:1621:ex2:words:2:zh":"the type you like","grammar:1621:ex2:words:2:note":"loanword","grammar:1621:ex2:words:2:pos":"noun","grammar:1621:ex2:words:3:zh":"(topic)","grammar:1621:ex2:words:3:pos":"particle","grammar:1621:ex2:words:4:zh":"what kind of","grammar:1621:ex2:words:4:pos":"pre-noun adjectival","grammar:1621:ex2:words:5:zh":"person","grammar:1621:ex2:words:5:note":"ひと","grammar:1621:ex2:words:5:pos":"noun","grammar:1621:ex2:words:6:zh":"is","grammar:1621:ex2:words:6:pos":"copula","grammar:1621:ex2:words:7:zh":"(question)","grammar:1621:ex2:words:7:pos":"particle","grammar:1621:ex2:points:0":"❗タイプ also means the type you like (who you are drawn to); どんな人 = what kind of person.","grammar:1621:ex2:points:1":"タイプ: the type you like.","grammar:1621:ex3:trans":"He is the fun type of friend.","grammar:1621:ex3:structure":"面白いタイプの〜です","grammar:1621:ex3:words:0:zh":"he","grammar:1621:ex3:words:0:note":"かれ","grammar:1621:ex3:words:0:pos":"pronoun","grammar:1621:ex3:words:1:zh":"(topic)","grammar:1621:ex3:words:1:pos":"particle","grammar:1621:ex3:words:2:zh":"interesting","grammar:1621:ex3:words:2:note":"おもしろい","grammar:1621:ex3:words:2:pos":"adjective","grammar:1621:ex3:words:3:zh":"type","grammar:1621:ex3:words:3:note":"loanword","grammar:1621:ex3:words:3:pos":"noun","grammar:1621:ex3:words:4:zh":"'s","grammar:1621:ex3:words:4:pos":"particle","grammar:1621:ex3:words:5:zh":"friend","grammar:1621:ex3:words:5:note":"ともだち","grammar:1621:ex3:words:5:pos":"noun","grammar:1621:ex3:words:6:zh":"is","grammar:1621:ex3:words:6:pos":"copula","grammar:1621:ex3:points:0":"❗面白いタイプ: the interesting type (of person).","grammar:1621:ex3:points:1":"面白いタイプ: the fun type.","grammar:1621:ex4:trans":"I like this type of game.","grammar:1621:ex4:structure":"このタイプの〜が好きです","grammar:1621:ex4:words:0:zh":"this","grammar:1621:ex4:words:0:pos":"pre-noun adjectival","grammar:1621:ex4:words:1:zh":"type","grammar:1621:ex4:words:1:note":"loanword","grammar:1621:ex4:words:1:pos":"noun","grammar:1621:ex4:words:2:zh":"'s","grammar:1621:ex4:words:2:pos":"particle","grammar:1621:ex4:words:3:zh":"game","grammar:1621:ex4:words:3:note":"loanword","grammar:1621:ex4:words:3:pos":"noun","grammar:1621:ex4:words:4:zh":"(object)","grammar:1621:ex4:words:4:pos":"particle","grammar:1621:ex4:words:5:zh":"to like","grammar:1621:ex4:words:5:note":"すき","grammar:1621:ex4:words:5:pos":"na-adjective","grammar:1621:ex4:words:6:zh":"(polite form)","grammar:1621:ex4:words:6:pos":"copula","grammar:1621:ex4:points:0":"❗このタイプのゲーム: this kind of game.","grammar:1621:ex4:points:1":"このタイプ: this type.","grammar:1621:ex5:trans":"Her type is a kind person.","grammar:1621:ex5:structure":"〜のタイプは〜人です","grammar:1621:ex5:words:0:zh":"she","grammar:1621:ex5:words:0:note":"かのじょ","grammar:1621:ex5:words:0:pos":"pronoun","grammar:1621:ex5:words:1:zh":"'s","grammar:1621:ex5:words:1:pos":"particle","grammar:1621:ex5:words:2:zh":"the type you like","grammar:1621:ex5:words:2:note":"loanword","grammar:1621:ex5:words:2:pos":"noun","grammar:1621:ex5:words:3:zh":"(topic)","grammar:1621:ex5:words:3:pos":"particle","grammar:1621:ex5:words:4:zh":"kind-hearted","grammar:1621:ex5:words:4:note":"やさしい","grammar:1621:ex5:words:4:pos":"adjective","grammar:1621:ex5:words:5:zh":"person","grammar:1621:ex5:words:5:note":"ひと","grammar:1621:ex5:words:5:pos":"noun","grammar:1621:ex5:words:6:zh":"is","grammar:1621:ex5:words:6:pos":"copula","grammar:1621:ex5:points:0":"❗彼女のタイプ: the type she likes; 優しい人 = a gentle person.","grammar:1621:ex5:points:1":"タイプは優しい人: her type is the gentle kind."},"1622":{"example:1622:exzh":"That guy is always late.","example:1622:exzh2":"I'm waiting for that guy to come.","example:1622:exzh3":"That guy is an interesting person.","example:1622:exzh4":"As for what he's thinking, that guy has no idea.","example:1622:exzh5":"I like that guy."},"1623":{"example:1623:exzh":"He received a guilty verdict.","example:1623:exzh2":"Evidence of guilt was found.","example:1623:exzh3":"She admitted her guilt at the trial.","example:1623:exzh4":"A guilty verdict requires sufficient evidence.","example:1623:exzh5":"Guilt has been confirmed in this case."},"1624":{"example:1624:exzh":"The details are written in this report.","example:1624:exzh2":"Please check the details of the product.","example:1624:exzh3":"Could you tell me the details?","example:1624:exzh4":"She wants to know the details.","example:1624:exzh5":"The details of this event are on the website."},"1625":{"example:1625:exzh":"He must settle the situation.","example:1625:exzh2":"This situation is very bad.","example:1625:exzh3":"Few people know the situation.","example:1625:exzh4":"Let's not talk about his situation.","example:1625:exzh5":"It's hard to explain the situation."},"1626":{"example:1626:exzh":"This fish smells bad.","example:1626:exzh2":"There's a bad smell.","example:1626:exzh3":"He was wearing smelly shoes.","example:1626:exzh4":"This garbage really stinks.","example:1626:exzh5":"The inside of the fridge somehow smells bad."},"1627":{"example:1627:exzh":"I'll go even if it rains.","example:1627:exzh2":"Even if I'm busy, I'll help.","example:1627:exzh3":"Even if it's difficult, let's give it a try.","example:1627:exzh4":"Even if I fail, I won't give up.","example:1627:exzh5":"Even if it's far, I'll go see you."},"1628":{"example:1628:exzh":"There's a presentation tomorrow.","example:1628:exzh2":"He announced a new project.","example:1628:exzh3":"Many people came to listen to the presentation.","example:1628:exzh4":"Are you ready for the presentation?","example:1628:exzh5":"I'll give the presentation based on this data.","grammar:1628:ex:trans":"There's a presentation tomorrow.","grammar:1628:ex:structure":"明日、発表があります","grammar:1628:ex:explain":"This sentence uses 「〜があります」 to show that an event or activity exists, and 「が」 marks the subject 「発表」. To say that there is an event or a scheduled item, use 「ある／あります」. The 「明日」 at the start is a time noun; here it sits at the beginning of the sentence as a time adverbial, and in casual speech 「に」 is often left out. 「発表」 is read 「はっぴょう」 and means a presentation or briefing session.","grammar:1628:ex:words:0:zh":"tomorrow","grammar:1628:ex:words:0:note":"あした","grammar:1628:ex:words:0:pos":"noun","grammar:1628:ex:words:1:zh":"present (announce)","grammar:1628:ex:words:1:note":"はっぴょう","grammar:1628:ex:words:1:pos":"noun","grammar:1628:ex:words:2:zh":"(nominative)","grammar:1628:ex:words:2:pos":"particle","grammar:1628:ex:words:3:zh":"there is / are","grammar:1628:ex:words:3:pos":"verb","grammar:1628:ex:points:0":"❗発表（はっぴょう）: announcement, publication, report; 発表がある = there is a presentation.","grammar:1628:ex:points:1":"発表: presentation.","grammar:1628:ex2:trans":"He announced a new project.","grammar:1628:ex2:structure":"〜を発表した","grammar:1628:ex2:words:0:zh":"he","grammar:1628:ex2:words:0:note":"かれ","grammar:1628:ex2:words:0:pos":"pronoun","grammar:1628:ex2:words:1:zh":"(topic)","grammar:1628:ex2:words:1:pos":"particle","grammar:1628:ex2:words:2:zh":"new","grammar:1628:ex2:words:2:note":"あたらしい","grammar:1628:ex2:words:2:pos":"adjective","grammar:1628:ex2:words:3:zh":"project","grammar:1628:ex2:words:3:note":"loanword","grammar:1628:ex2:words:3:pos":"noun","grammar:1628:ex2:words:4:zh":"(object marker)","grammar:1628:ex2:words:4:pos":"particle","grammar:1628:ex2:words:5:zh":"announced","grammar:1628:ex2:words:5:note":"はっぴょうした","grammar:1628:ex2:words:5:pos":"verb","grammar:1628:ex2:points:0":"❗発表する: to announce, to make public; プロジェクトを発表 = announce a project.","grammar:1628:ex2:points:1":"発表する: to present, to announce.","grammar:1628:ex3:trans":"Many people came to listen to the presentation.","grammar:1628:ex3:structure":"〜を聞きに来た","grammar:1628:ex3:words:0:zh":"many","grammar:1628:ex3:words:0:note":"おおく","grammar:1628:ex3:words:0:pos":"noun","grammar:1628:ex3:words:1:zh":"'s","grammar:1628:ex3:words:1:pos":"particle","grammar:1628:ex3:words:2:zh":"person","grammar:1628:ex3:words:2:note":"ひと","grammar:1628:ex3:words:2:pos":"noun","grammar:1628:ex3:words:3:zh":"(nominative)","grammar:1628:ex3:words:3:pos":"particle","grammar:1628:ex3:words:4:zh":"present (announce)","grammar:1628:ex3:words:4:note":"はっぴょう","grammar:1628:ex3:words:4:pos":"noun","grammar:1628:ex3:words:5:zh":"(object marker)","grammar:1628:ex3:words:5:pos":"particle","grammar:1628:ex3:words:6:zh":"listen","grammar:1628:ex3:words:6:note":"きき","grammar:1628:ex3:words:6:pos":"verb","grammar:1628:ex3:words:7:zh":"(purpose)","grammar:1628:ex3:words:7:pos":"particle","grammar:1628:ex3:words:8:zh":"came","grammar:1628:ex3:words:8:note":"きた","grammar:1628:ex3:words:8:pos":"verb","grammar:1628:ex3:points:0":"❗〜を聞きに来る: come to listen to … (masu-form of a verb + に); 発表を聞く = listen to a presentation.","grammar:1628:ex3:points:1":"聞きに来る: come to listen.","grammar:1628:ex4:trans":"Are you ready for the presentation?","grammar:1628:ex4:structure":"発表の準備はできましたか","grammar:1628:ex4:words:0:zh":"present (announce)","grammar:1628:ex4:words:0:note":"はっぴょう","grammar:1628:ex4:words:0:pos":"noun","grammar:1628:ex4:words:1:zh":"'s","grammar:1628:ex4:words:1:pos":"particle","grammar:1628:ex4:words:2:zh":"prepare","grammar:1628:ex4:words:2:note":"じゅんび","grammar:1628:ex4:words:2:pos":"noun","grammar:1628:ex4:words:3:zh":"(topic)","grammar:1628:ex4:words:3:pos":"particle","grammar:1628:ex4:words:4:zh":"done","grammar:1628:ex4:words:4:pos":"verb","grammar:1628:ex4:words:5:zh":"(question)","grammar:1628:ex4:words:5:pos":"particle","grammar:1628:ex4:points:0":"❗発表の準備: preparing a presentation; 準備ができる = be ready.","grammar:1628:ex4:points:1":"発表の準備: getting a presentation ready.","grammar:1628:ex5:trans":"I'll present based on this data.","grammar:1628:ex5:structure":"〜を基に、発表します","grammar:1628:ex5:words:0:zh":"this","grammar:1628:ex5:words:0:pos":"pre-noun adjectival","grammar:1628:ex5:words:1:zh":"data","grammar:1628:ex5:words:1:note":"loanword","grammar:1628:ex5:words:1:pos":"noun","grammar:1628:ex5:words:2:zh":"(object marker)","grammar:1628:ex5:words:2:pos":"particle","grammar:1628:ex5:words:3:zh":"based on","grammar:1628:ex5:words:3:note":"もとに","grammar:1628:ex5:words:3:pos":"set phrase","grammar:1628:ex5:words:4:zh":"present (announce)","grammar:1628:ex5:words:4:note":"はっぴょうします","grammar:1628:ex5:words:4:pos":"verb","grammar:1628:ex5:points:0":"❗〜を基に: using … as a basis; データを基に = based on the data.","grammar:1628:ex5:points:1":"〜を基に: based on."},"1630":{"example:1630:exzh":"California is a beautiful place.","example:1630:exzh2":"He lives in California.","example:1630:exzh3":"The weather in California is nice.","example:1630:exzh4":"There are many tourist spots in California.","example:1630:exzh5":"I've been to California."},"1631":{"example:1631:exzh":"The phone won't connect.","example:1631:exzh2":"I have a good relationship with him.","example:1631:exzh3":"It's connected to the internet.","example:1631:exzh4":"Staying connected with family is important.","example:1631:exzh5":"This story is connected to the past."},"1632":{"example:1632:exzh":"A new lab has been opened.","example:1632:exzh2":"I'm doing research in the lab.","example:1632:exzh3":"The lab's equipment is the latest.","example:1632:exzh4":"She is conducting experiments in the lab.","example:1632:exzh5":"The lab will be ready to use soon."},"1633":{"example:1633:exzh":"There are many fruits I like, for example apples and oranges.","example:1633:exzh2":"My hobby is, for example, drawing pictures.","example:1633:exzh3":"For example, this problem is difficult.","example:1633:exzh4":"For example, family and friends are important.","example:1633:exzh5":"For example, I like traveling.","grammar:1633:ex:trans":"There are many fruits I like, for example apples and mandarin oranges.","grammar:1633:ex:structure":"名詞はたくさんあります。例えば、名詞や名詞です","grammar:1633:ex:explain":"「例えば」 is used to give examples. Usually you first state the general point (here, that there are many fruits you like), then introduce concrete examples with 「例えば」. It often pairs with 「や」 or 「など」 in a list, as in 「例えば、りんごやみかんなど」. In conversation, people also ask 「例えば？」 on its own to ask for an example.","grammar:1633:ex:words:0:zh":"liked / favorite","grammar:1633:ex:words:0:note":"すきな: na-adjective in its pre-noun (modifying) form","grammar:1633:ex:words:0:pos":"na-adjective","grammar:1633:ex:words:1:zh":"fruit","grammar:1633:ex:words:1:note":"くだもの: irregular reading","grammar:1633:ex:words:1:pos":"noun","grammar:1633:ex:words:2:zh":"marks the topic","grammar:1633:ex:words:2:pos":"particle","grammar:1633:ex:words:3:zh":"a lot","grammar:1633:ex:words:3:pos":"adverb","grammar:1633:ex:words:4:zh":"there is / are","grammar:1633:ex:words:4:pos":"verb","grammar:1633:ex:words:5:zh":"polite ending","grammar:1633:ex:words:5:pos":"auxiliary verb","grammar:1633:ex:words:6:zh":"for example","grammar:1633:ex:words:6:note":"たとえば: used when giving examples","grammar:1633:ex:words:6:pos":"adverb","grammar:1633:ex:words:7:zh":"apple","grammar:1633:ex:words:7:pos":"noun","grammar:1633:ex:words:8:zh":"and (listing some items)","grammar:1633:ex:words:8:pos":"particle","grammar:1633:ex:words:9:zh":"mandarin orange","grammar:1633:ex:words:9:pos":"noun","grammar:1633:ex:words:10:zh":"is","grammar:1633:ex:words:10:pos":"copula","grammar:1633:ex:points:0":"「例えば、」 comes at the start of the second sentence and gives specific examples from the previous sentence, 「好きな果物はたくさんあります」.","grammar:1633:ex:points:1":"The 「や」 in 「りんごやみかん」 lists only some examples, suggesting there are other fruits too.","grammar:1633:ex:points:2":"In 「好きな果物」, 「好き」 is a na-adjective, so it takes 「な」 when modifying a noun.","grammar:1633:ex2:trans":"My hobby is, for example, drawing pictures.","grammar:1633:ex2:structure":"〜は、例えば〜ことです","grammar:1633:ex2:words:0:zh":"I","grammar:1633:ex2:words:0:note":"わたし","grammar:1633:ex2:words:0:pos":"pronoun","grammar:1633:ex2:words:1:zh":"'s","grammar:1633:ex2:words:1:pos":"particle","grammar:1633:ex2:words:2:zh":"interest","grammar:1633:ex2:words:2:note":"しゅみ","grammar:1633:ex2:words:2:pos":"noun","grammar:1633:ex2:words:3:zh":"(topic)","grammar:1633:ex2:words:3:pos":"particle","grammar:1633:ex2:words:4:zh":"for example","grammar:1633:ex2:words:4:note":"たとえば","grammar:1633:ex2:words:4:pos":"adverb","grammar:1633:ex2:words:5:zh":"picture","grammar:1633:ex2:words:5:note":"え","grammar:1633:ex2:words:5:pos":"noun","grammar:1633:ex2:words:6:zh":"(object marker)","grammar:1633:ex2:words:6:pos":"particle","grammar:1633:ex2:words:7:zh":"picture","grammar:1633:ex2:words:7:note":"かく","grammar:1633:ex2:words:7:pos":"verb","grammar:1633:ex2:words:8:zh":"(nominalizer)","grammar:1633:ex2:words:8:pos":"noun","grammar:1633:ex2:words:9:zh":"is","grammar:1633:ex2:words:9:pos":"copula","grammar:1633:ex2:points:0":"❗例えば + a concrete example: giving an example; 趣味は例えば… = my hobby is, for example, …","grammar:1633:ex2:points:1":"例えば: for example.","grammar:1633:ex3:trans":"For example, this problem is difficult.","grammar:1633:ex3:structure":"例えば、〜は難しいです","grammar:1633:ex3:words:0:zh":"for example","grammar:1633:ex3:words:0:note":"たとえば","grammar:1633:ex3:words:0:pos":"adverb","grammar:1633:ex3:words:1:zh":"this","grammar:1633:ex3:words:1:pos":"pre-noun adjectival","grammar:1633:ex3:words:2:zh":"problem","grammar:1633:ex3:words:2:note":"もんだい","grammar:1633:ex3:words:2:pos":"noun","grammar:1633:ex3:words:3:zh":"(topic)","grammar:1633:ex3:words:3:pos":"particle","grammar:1633:ex3:words:4:zh":"difficult","grammar:1633:ex3:words:4:note":"むずかしい","grammar:1633:ex3:words:4:pos":"adjective","grammar:1633:ex3:words:5:zh":"(polite form)","grammar:1633:ex3:words:5:pos":"copula","grammar:1633:ex3:points:0":"❗例えば〜: for example … (introducing an actual case).","grammar:1633:ex3:points:1":"例えば: for example.","grammar:1633:ex4:trans":"For example, family and friends are important.","grammar:1633:ex4:structure":"例えば、〜や〜が大切です","grammar:1633:ex4:words:0:zh":"for example","grammar:1633:ex4:words:0:note":"たとえば","grammar:1633:ex4:words:0:pos":"adverb","grammar:1633:ex4:words:1:zh":"family","grammar:1633:ex4:words:1:note":"かぞく","grammar:1633:ex4:words:1:pos":"noun","grammar:1633:ex4:words:2:zh":"with","grammar:1633:ex4:words:2:pos":"particle","grammar:1633:ex4:words:3:zh":"friend","grammar:1633:ex4:words:3:note":"ゆうじん","grammar:1633:ex4:words:3:pos":"noun","grammar:1633:ex4:words:4:zh":"(nominative)","grammar:1633:ex4:words:4:pos":"particle","grammar:1633:ex4:words:5:zh":"important","grammar:1633:ex4:words:5:note":"たいせつ","grammar:1633:ex4:words:5:pos":"na-adjective","grammar:1633:ex4:words:6:zh":"(polite form)","grammar:1633:ex4:words:6:pos":"copula","grammar:1633:ex4:points:0":"❗〜や〜: … and … and so on (listing); 例えば = for example.","grammar:1633:ex4:points:1":"〜や〜: and so on.","grammar:1633:ex5:trans":"For example, I like traveling.","grammar:1633:ex5:structure":"例えば、〜が好きです","grammar:1633:ex5:words:0:zh":"for example","grammar:1633:ex5:words:0:note":"たとえば","grammar:1633:ex5:words:0:pos":"adverb","grammar:1633:ex5:words:1:zh":"travel / trip","grammar:1633:ex5:words:1:note":"りょこう","grammar:1633:ex5:words:1:pos":"noun","grammar:1633:ex5:words:2:zh":"(object)","grammar:1633:ex5:words:2:pos":"particle","grammar:1633:ex5:words:3:zh":"to like","grammar:1633:ex5:words:3:note":"すき","grammar:1633:ex5:words:3:pos":"na-adjective","grammar:1633:ex5:words:4:zh":"(polite form)","grammar:1633:ex5:words:4:pos":"copula","grammar:1633:ex5:points:0":"❗例えば旅行が好き: for example, liking travel.","grammar:1633:ex5:points:1":"例えば: for example."},"1635":{"example:1635:exzh":"I play in the park.","example:1635:exzh2":"He is a civil servant.","example:1635:exzh3":"Let's be quiet in public places.","example:1635:exzh4":"I'll announce it publicly.","example:1635:exzh5":"That person is publicly known, and everyone knows about them."},"1636":{"example:1636:exzh":"I draw a line horizontally.","example:1636:exzh2":"Please move to the side.","example:1636:exzh3":"This path spreads out sideways.","example:1636:exzh4":"I talk with the person next to me.","example:1636:exzh5":"Please place the paper sideways.","grammar:1636:ex:trans":"I draw a line horizontally.","grammar:1636:ex:structure":"横に線を引きます","grammar:1636:ex:explain":"「横」 is a noun showing direction; with 「に」 it describes the direction in which the line is drawn. 「線を」 uses 「を」 to mark what is drawn. 「引く」 usually means to pull, but in 「線を引く」 it means to draw a line. 「引きます」 is its polite form.","grammar:1636:ex:words:0:zh":"horizontally","grammar:1636:ex:words:0:note":"よこ","grammar:1636:ex:words:0:pos":"noun","grammar:1636:ex:words:1:zh":"(direction of the action)","grammar:1636:ex:words:1:pos":"particle","grammar:1636:ex:words:2:zh":"line","grammar:1636:ex:words:2:note":"せん","grammar:1636:ex:words:2:pos":"noun","grammar:1636:ex:words:3:zh":"(object)","grammar:1636:ex:words:3:pos":"particle","grammar:1636:ex:words:4:zh":"draw","grammar:1636:ex:words:4:note":"ひき","grammar:1636:ex:words:4:pos":"verb","grammar:1636:ex:words:5:zh":"(polite ending)","grammar:1636:ex:words:5:pos":"auxiliary verb","grammar:1636:ex:points:0":"Here 「横に」 means the action is done horizontally.","grammar:1636:ex:points:1":"「線を引く」 is a fixed collocation meaning to draw a line.","grammar:1636:ex2:trans":"Please move to the side.","grammar:1636:ex2:structure":"横に移動してください","grammar:1636:ex2:words:0:zh":"beside, next to","grammar:1636:ex2:words:0:note":"よこ","grammar:1636:ex2:words:0:pos":"noun","grammar:1636:ex2:words:1:zh":"(direction)","grammar:1636:ex2:words:1:pos":"particle","grammar:1636:ex2:words:2:zh":"move","grammar:1636:ex2:words:2:note":"いどうして","grammar:1636:ex2:words:2:pos":"verb","grammar:1636:ex2:words:3:zh":"please","grammar:1636:ex2:words:3:pos":"auxiliary verb","grammar:1636:ex2:points:0":"❗横に: to the side, sideways; 横に移動 = move to the side.","grammar:1636:ex2:points:1":"横に移動: move to the side.","grammar:1636:ex3:trans":"This road stretches out sideways.","grammar:1636:ex3:structure":"〜は横に広がっている","grammar:1636:ex3:words:0:zh":"this","grammar:1636:ex3:words:0:pos":"pre-noun adjectival","grammar:1636:ex3:words:1:zh":"road","grammar:1636:ex3:words:1:note":"みち","grammar:1636:ex3:words:1:pos":"noun","grammar:1636:ex3:words:2:zh":"(topic)","grammar:1636:ex3:words:2:pos":"particle","grammar:1636:ex3:words:3:zh":"horizontally","grammar:1636:ex3:words:3:note":"よこ","grammar:1636:ex3:words:3:pos":"noun","grammar:1636:ex3:words:4:zh":"(direction)","grammar:1636:ex3:words:4:pos":"particle","grammar:1636:ex3:words:5:zh":"stretches","grammar:1636:ex3:words:5:note":"ひろがっている","grammar:1636:ex3:words:5:pos":"verb","grammar:1636:ex3:points:0":"❗横に広がる: spread out sideways; 広がる = spread (intransitive verb).","grammar:1636:ex3:points:1":"横に広がる: spread sideways.","grammar:1636:ex4:trans":"Talk with the person beside you.","grammar:1636:ex4:structure":"横の人と話す","grammar:1636:ex4:words:0:zh":"beside, next to","grammar:1636:ex4:words:0:note":"よこ","grammar:1636:ex4:words:0:pos":"noun","grammar:1636:ex4:words:1:zh":"'s","grammar:1636:ex4:words:1:pos":"particle","grammar:1636:ex4:words:2:zh":"person","grammar:1636:ex4:words:2:note":"ひと","grammar:1636:ex4:words:2:pos":"noun","grammar:1636:ex4:words:3:zh":"(object)","grammar:1636:ex4:words:3:pos":"particle","grammar:1636:ex4:words:4:zh":"chat","grammar:1636:ex4:words:4:note":"はなす","grammar:1636:ex4:words:4:pos":"verb","grammar:1636:ex4:points:0":"❗横の人: the person beside you (横 = the side).","grammar:1636:ex4:points:1":"横の人: the person in the next seat.","grammar:1636:ex5:trans":"Please place the paper sideways.","grammar:1636:ex5:structure":"〜を横にして置いてください","grammar:1636:ex5:words:0:zh":"paper","grammar:1636:ex5:words:0:note":"かみ","grammar:1636:ex5:words:0:pos":"noun","grammar:1636:ex5:words:1:zh":"(object)","grammar:1636:ex5:words:1:pos":"particle","grammar:1636:ex5:words:2:zh":"horizontally","grammar:1636:ex5:words:2:note":"よこ","grammar:1636:ex5:words:2:pos":"noun","grammar:1636:ex5:words:3:zh":"(result of the change)","grammar:1636:ex5:words:3:pos":"particle","grammar:1636:ex5:words:4:zh":"turn it into","grammar:1636:ex5:words:4:pos":"verb","grammar:1636:ex5:words:5:zh":"put","grammar:1636:ex5:words:5:note":"おいて: te-form of 置く","grammar:1636:ex5:words:5:pos":"verb","grammar:1636:ex5:words:6:zh":"please","grammar:1636:ex5:words:6:pos":"auxiliary verb","grammar:1636:ex5:points:0":"❗横にして: here 横（よこ） means horizontal (as opposed to vertical 縦), and 「横にする」 means to turn the paper to a horizontal orientation.","grammar:1636:ex5:points:1":"〜にする: to make something become 〜; here, to turn it sideways.","grammar:1636:ex5:points:2":"〜てください: politely asking someone to do something.","exam:1636:zh":"This photo is longer horizontally, not vertically, so please print it on paper that's longer horizontally.","exam:1636:why":"The direction opposite 「縦」 is 「横」. 「前」 means the front, so it can't express a photo's horizontal length."},"1637":{"example:1637:exzh":"Please tell me a day that works for you.","example:1637:exzh2":"I'll take his circumstances into account.","example:1637:exzh3":"It's inconvenient.","example:1637:exzh4":"It's hard to arrange a time.","example:1637:exzh5":"I hope the timing works out."},"1638":{"example:1638:exzh":"He silently turned his back on me.","example:1638:exzh2":"Please straighten your back.","example:1638:exzh3":"He is tall.","example:1638:exzh4":"I'll give you a push on the back.","example:1638:exzh5":"Please stand with your back against the wall.","grammar:1638:ex:trans":"He turned his back on me without a word.","grammar:1638:ex:structure":"名詞は＋動詞て＋名詞に＋背を向けた","grammar:1638:ex:explain":"「背」 is read 「せ」 and means back, but in everyday speech the body part is usually called 「背中」. 「背」 often appears in fixed expressions such as 「背を向ける」 (turn one's back), 「背を伸ばす」 (straighten one's back), and 「背が高い」 (be tall). Here 「背を向けた」 literally means turning one's back, and it also carries the nuance of shutting the other person out.","grammar:1638:ex:words:0:zh":"he","grammar:1638:ex:words:0:note":"かれ","grammar:1638:ex:words:0:pos":"pronoun","grammar:1638:ex:words:1:zh":"marks the topic","grammar:1638:ex:words:1:pos":"particle","grammar:1638:ex:words:2:zh":"silent","grammar:1638:ex:words:2:note":"だまっ: te-form of 黙る, used in the continuative","grammar:1638:ex:words:2:pos":"verb","grammar:1638:ex:words:3:zh":"connects (showing state)","grammar:1638:ex:words:3:pos":"particle","grammar:1638:ex:words:4:zh":"I","grammar:1638:ex:words:4:note":"わたし","grammar:1638:ex:words:4:pos":"pronoun","grammar:1638:ex:words:5:zh":"(object)","grammar:1638:ex:words:5:pos":"particle","grammar:1638:ex:words:6:zh":"back","grammar:1638:ex:words:6:note":"せ","grammar:1638:ex:words:6:pos":"noun","grammar:1638:ex:words:7:zh":"object marker","grammar:1638:ex:words:7:pos":"particle","grammar:1638:ex:words:8:zh":"heading toward","grammar:1638:ex:words:8:note":"むけ: ta-form of 向ける, used in the continuative","grammar:1638:ex:words:8:pos":"verb","grammar:1638:ex:words:9:zh":"the past","grammar:1638:ex:words:9:pos":"auxiliary verb","grammar:1638:ex:points:0":"「背を向ける」 is a fixed expression meaning to turn one's back; it can also figuratively mean being cold or ignoring someone.","grammar:1638:ex:points:1":"The 「に」 in 「私に」 marks the person being turned away from.","grammar:1638:ex:points:2":"「黙って」 uses the te-form to show the state in which the action happens: without speaking.","grammar:1638:ex2:trans":"Please straighten your back.","grammar:1638:ex2:structure":"背を＋伸ばして＋ください","grammar:1638:ex2:words:0:zh":"back","grammar:1638:ex2:words:0:note":"せ","grammar:1638:ex2:words:0:pos":"noun","grammar:1638:ex2:words:1:zh":"object marker","grammar:1638:ex2:words:1:pos":"particle","grammar:1638:ex2:words:2:zh":"straighten, stretch","grammar:1638:ex2:words:2:note":"のばして: te-form of 伸ばす","grammar:1638:ex2:words:2:pos":"verb","grammar:1638:ex2:words:3:zh":"please","grammar:1638:ex2:words:3:pos":"auxiliary verb","grammar:1638:ex2:points:0":"「背を伸ばす」 means to straighten or stretch your back.","grammar:1638:ex2:points:1":"「てください」 attaches to the te-form to ask someone to do something.","grammar:1638:ex3:trans":"He is tall.","grammar:1638:ex3:structure":"〜は背が高い","grammar:1638:ex3:words:0:zh":"he","grammar:1638:ex3:words:0:note":"かれ","grammar:1638:ex3:words:0:pos":"pronoun","grammar:1638:ex3:words:1:zh":"(topic)","grammar:1638:ex3:words:1:pos":"particle","grammar:1638:ex3:words:2:zh":"height","grammar:1638:ex3:words:2:note":"せ","grammar:1638:ex3:words:2:pos":"noun","grammar:1638:ex3:words:3:zh":"(nominative)","grammar:1638:ex3:words:3:pos":"particle","grammar:1638:ex3:words:4:zh":"tall","grammar:1638:ex3:words:4:note":"たかい","grammar:1638:ex3:words:4:pos":"adjective","grammar:1638:ex3:points:0":"❗背が高い: be tall (here 『背』 means height; idiomatic).","grammar:1638:ex3:points:1":"背が高い: be tall.","grammar:1638:ex4:trans":"I'll give your back a push.","grammar:1638:ex4:structure":"背中を押してあげる","grammar:1638:ex4:words:0:zh":"back","grammar:1638:ex4:words:0:note":"せなか","grammar:1638:ex4:words:0:pos":"noun","grammar:1638:ex4:words:1:zh":"(object marker)","grammar:1638:ex4:words:1:pos":"particle","grammar:1638:ex4:words:2:zh":"push","grammar:1638:ex4:words:2:note":"おして","grammar:1638:ex4:words:2:pos":"verb","grammar:1638:ex4:words:3:zh":"(do for you)","grammar:1638:ex4:words:3:pos":"auxiliary verb","grammar:1638:ex4:points:0":"❗背中を押す: push someone's back, and figuratively give them a nudge of encouragement (idiomatic); 〜てあげる = do something for someone.","grammar:1638:ex4:points:1":"背中を押す: give someone a push.","grammar:1638:ex5:trans":"Please stand with your back against the wall.","grammar:1638:ex5:structure":"名詞に＋背をつけて＋立ってください","grammar:1638:ex5:words:0:zh":"wall","grammar:1638:ex5:words:0:note":"かべ","grammar:1638:ex5:words:0:pos":"noun","grammar:1638:ex5:words:1:zh":"(the surface it rests against)","grammar:1638:ex5:words:1:pos":"particle","grammar:1638:ex5:words:2:zh":"back","grammar:1638:ex5:words:2:note":"せ","grammar:1638:ex5:words:2:pos":"noun","grammar:1638:ex5:words:3:zh":"object marker","grammar:1638:ex5:words:3:pos":"particle","grammar:1638:ex5:words:4:zh":"put against","grammar:1638:ex5:words:4:pos":"verb","grammar:1638:ex5:words:5:zh":"links","grammar:1638:ex5:words:5:pos":"particle","grammar:1638:ex5:words:6:zh":"stand","grammar:1638:ex5:words:6:note":"たっ: te-form of 立つ, used in the continuative","grammar:1638:ex5:words:6:pos":"verb","grammar:1638:ex5:words:7:zh":"links","grammar:1638:ex5:words:7:pos":"particle","grammar:1638:ex5:words:8:zh":"please","grammar:1638:ex5:words:8:pos":"auxiliary verb","grammar:1638:ex5:points:0":"「背をつける」 means to put your back against something; here, against the wall.","grammar:1638:ex5:points:1":"「つけて立って」 links two te-forms, showing that you put your back to the wall and then stand.","grammar:1638:ex5:points:2":"「てください」 is a polite request."},"1639":{"example:1639:exzh":"He is a science student.","example:1639:exzh2":"I want to enter a social sciences faculty at university.","example:1639:exzh3":"Humanities and sciences.","example:1639:exzh4":"This program is in the information field.","example:1639:exzh5":"She chose a career in the arts."},"1641":{"example:1641:exzh":"It's something that can't be helped.","example:1641:exzh2":"There's nothing to be done now.","example:1641:exzh3":"I gave up reluctantly.","example:1641:exzh4":"It was an unavoidable choice.","example:1641:exzh5":"Sometimes there are things that can't be helped."},"1642":{"example:1642:exzh":"Please take a look at this map.","example:1642:exzh2":"You don't have a map with you?","example:1642:exzh3":"Where can I buy a map?","example:1642:exzh4":"A map is a travel essential.","example:1642:exzh5":"This map is very easy to understand.","grammar:1642:ex:trans":"Please take a look at this map.","grammar:1642:ex:structure":"〜を見てください (please look at 〜)","grammar:1642:ex:explain":"This sentence uses the polite request pattern 「〜てください」 = “please …,” formed from the te-form of the verb 「見る」, 「見て」, plus 「ください」. 「を」 marks 「地図」 as the object of 「見る」. 「この」 is a pre-noun adjectival that directly modifies 「地図」. The whole sentence politely asks the other person to look at this map. 「地図」 is read 「ちず」.","grammar:1642:ex:words:0:zh":"this","grammar:1642:ex:words:0:pos":"pre-noun adjectival","grammar:1642:ex:words:1:zh":"map","grammar:1642:ex:words:1:note":"ちず","grammar:1642:ex:words:1:pos":"noun","grammar:1642:ex:words:2:zh":"(object marker)","grammar:1642:ex:words:2:pos":"particle","grammar:1642:ex:words:3:zh":"look","grammar:1642:ex:words:3:note":"みて","grammar:1642:ex:words:3:pos":"verb","grammar:1642:ex:words:4:zh":"please","grammar:1642:ex:words:4:pos":"auxiliary verb","grammar:1642:ex:points:0":"❗地図（ちず）: map; 地図を見る = look at a map.","grammar:1642:ex:points:1":"地図: map.","grammar:1642:ex2:trans":"Don't you have a map with you?","grammar:1642:ex2:structure":"地図を持っていませんか","grammar:1642:ex2:words:0:zh":"map","grammar:1642:ex2:words:0:note":"ちず","grammar:1642:ex2:words:0:pos":"noun","grammar:1642:ex2:words:1:zh":"(object marker)","grammar:1642:ex2:words:1:pos":"particle","grammar:1642:ex2:words:2:zh":"don't have (with us)","grammar:1642:ex2:words:2:note":"もっていません","grammar:1642:ex2:words:2:pos":"verb","grammar:1642:ex2:words:3:zh":"(question)","grammar:1642:ex2:words:3:pos":"particle","grammar:1642:ex2:points:0":"❗地図を持つ: to carry a map; 〜ていませんか = don't you have …?","grammar:1642:ex2:points:1":"地図を持つ: to carry a map.","grammar:1642:ex3:trans":"Where can I buy a map?","grammar:1642:ex3:structure":"どこで地図を買えますか","grammar:1642:ex3:words:0:zh":"where","grammar:1642:ex3:words:0:pos":"pronoun","grammar:1642:ex3:words:1:zh":"(place)","grammar:1642:ex3:words:1:pos":"particle","grammar:1642:ex3:words:2:zh":"map","grammar:1642:ex3:words:2:note":"ちず","grammar:1642:ex3:words:2:pos":"noun","grammar:1642:ex3:words:3:zh":"(object marker)","grammar:1642:ex3:words:3:pos":"particle","grammar:1642:ex3:words:4:zh":"can buy","grammar:1642:ex3:words:4:note":"かえます","grammar:1642:ex3:words:4:pos":"verb","grammar:1642:ex3:words:5:zh":"(question)","grammar:1642:ex3:words:5:pos":"particle","grammar:1642:ex3:points:0":"❗買える: can buy (potential form of 買う); ❓どこで = where (で for place).","grammar:1642:ex3:points:1":"買える: can buy.","grammar:1642:ex4:trans":"A map is a travel essential.","grammar:1642:ex4:structure":"〜は〜の必需品です","grammar:1642:ex4:words:0:zh":"map","grammar:1642:ex4:words:0:note":"ちず","grammar:1642:ex4:words:0:pos":"noun","grammar:1642:ex4:words:1:zh":"(topic)","grammar:1642:ex4:words:1:pos":"particle","grammar:1642:ex4:words:2:zh":"travel / trip","grammar:1642:ex4:words:2:note":"りょこう","grammar:1642:ex4:words:2:pos":"noun","grammar:1642:ex4:words:3:zh":"'s","grammar:1642:ex4:words:3:pos":"particle","grammar:1642:ex4:words:4:zh":"essential item","grammar:1642:ex4:words:4:note":"ひつじゅひん","grammar:1642:ex4:words:4:pos":"noun","grammar:1642:ex4:words:5:zh":"is","grammar:1642:ex4:words:5:pos":"copula","grammar:1642:ex4:points:0":"❗必需品: essential item; 旅行の必需品 = a must-have for travel.","grammar:1642:ex4:points:1":"必需品: must-have item.","grammar:1642:ex5:trans":"This map is very easy to understand.","grammar:1642:ex5:structure":"〜はとても分かりやすいです","grammar:1642:ex5:words:0:zh":"this","grammar:1642:ex5:words:0:pos":"pre-noun adjectival","grammar:1642:ex5:words:1:zh":"map","grammar:1642:ex5:words:1:note":"ちず","grammar:1642:ex5:words:1:pos":"noun","grammar:1642:ex5:words:2:zh":"(topic)","grammar:1642:ex5:words:2:pos":"particle","grammar:1642:ex5:words:3:zh":"extremely","grammar:1642:ex5:words:3:pos":"adverb","grammar:1642:ex5:words:4:zh":"easy to understand","grammar:1642:ex5:words:4:note":"わかりやすい","grammar:1642:ex5:words:4:pos":"verb","grammar:1642:ex5:words:5:zh":"(polite form)","grammar:1642:ex5:words:5:pos":"copula","grammar:1642:ex5:points:0":"❗〜やすい: easy to … (分かりやすい = easy to understand).","grammar:1642:ex5:points:1":"分かりやすい: easy to understand.","exam:1642:zh":"I didn't know the way from the station to the hotel, so I looked at a map.","exam:1642:why":"A 「地図」 lets you check locations and routes. A 「切符」 is a ticket for riding, and it can't show you the way to the hotel."},"1643":{"example:1643:exzh":"Where is the bus that goes to the airport?","example:1643:exzh2":"I'll meet a friend at the airport.","example:1643:exzh3":"The airport is outside the city.","example:1643:exzh4":"The airport is a busy place.","example:1643:exzh5":"This airport is new and clean.","grammar:1643:ex:trans":"Where is the bus that goes to the airport?","grammar:1643:ex:structure":"〜に行くバスはどこですか","grammar:1643:ex:explain":"The core of this sentence is that the plain form of the verb, 「空港に行く」, directly modifies the noun 「バス」, making “the bus that goes to the airport”; in Japanese, verbs take the plain form when they modify a noun. Here 「に」 marks the destination of movement, 「空港」. The second half, 「〜はどこですか」, is the standard way to ask where something is, and the sentence-final 「か」 is the question particle. 「空港」 is read 「くうこう」.","grammar:1643:ex:words:0:zh":"airport","grammar:1643:ex:words:0:note":"くうこう","grammar:1643:ex:words:0:pos":"noun","grammar:1643:ex:words:1:zh":"(destination)","grammar:1643:ex:words:1:pos":"particle","grammar:1643:ex:words:2:zh":"go","grammar:1643:ex:words:2:note":"いく","grammar:1643:ex:words:2:pos":"verb","grammar:1643:ex:words:3:zh":"bus","grammar:1643:ex:words:3:note":"loanword","grammar:1643:ex:words:3:pos":"noun","grammar:1643:ex:words:4:zh":"(topic)","grammar:1643:ex:words:4:pos":"particle","grammar:1643:ex:words:5:zh":"where","grammar:1643:ex:words:5:pos":"pronoun","grammar:1643:ex:words:6:zh":"is","grammar:1643:ex:words:6:pos":"copula","grammar:1643:ex:words:7:zh":"(question)","grammar:1643:ex:words:7:pos":"particle","grammar:1643:ex:points:0":"❗空港（くうこう）: airport; 空港に行くバス = the bus that goes to the airport.","grammar:1643:ex:points:1":"空港: airport.","grammar:1643:ex2:trans":"I'll pick up a friend at the airport.","grammar:1643:ex2:structure":"〜で〜を迎えます","grammar:1643:ex2:words:0:zh":"I","grammar:1643:ex2:words:0:note":"わたし","grammar:1643:ex2:words:0:pos":"pronoun","grammar:1643:ex2:words:1:zh":"(topic)","grammar:1643:ex2:words:1:pos":"particle","grammar:1643:ex2:words:2:zh":"airport","grammar:1643:ex2:words:2:note":"くうこう","grammar:1643:ex2:words:2:pos":"noun","grammar:1643:ex2:words:3:zh":"(place)","grammar:1643:ex2:words:3:pos":"particle","grammar:1643:ex2:words:4:zh":"friend","grammar:1643:ex2:words:4:note":"ともだち","grammar:1643:ex2:words:4:pos":"noun","grammar:1643:ex2:words:5:zh":"(object marker)","grammar:1643:ex2:words:5:pos":"particle","grammar:1643:ex2:words:6:zh":"pick up","grammar:1643:ex2:words:6:note":"むかえます","grammar:1643:ex2:words:6:pos":"verb","grammar:1643:ex2:points:0":"❗迎える: to pick up, to welcome; ❓空港で = at the airport (で for place).","grammar:1643:ex2:points:1":"迎える: to welcome.","grammar:1643:ex3:trans":"The airport is outside the city.","grammar:1643:ex3:structure":"〜は〜の外にあります","grammar:1643:ex3:words:0:zh":"airport","grammar:1643:ex3:words:0:note":"くうこう","grammar:1643:ex3:words:0:pos":"noun","grammar:1643:ex3:words:1:zh":"(topic)","grammar:1643:ex3:words:1:pos":"particle","grammar:1643:ex3:words:2:zh":"city","grammar:1643:ex3:words:2:note":"し","grammar:1643:ex3:words:2:pos":"noun","grammar:1643:ex3:words:3:zh":"'s","grammar:1643:ex3:words:3:pos":"particle","grammar:1643:ex3:words:4:zh":"outside","grammar:1643:ex3:words:4:note":"そと","grammar:1643:ex3:words:4:pos":"noun","grammar:1643:ex3:words:5:zh":"(location of existence)","grammar:1643:ex3:words:5:pos":"particle","grammar:1643:ex3:words:6:zh":"there is / are","grammar:1643:ex3:words:6:pos":"verb","grammar:1643:ex3:points:0":"❗市の外: outside the city, on the outskirts; 空港 = airport.","grammar:1643:ex3:points:1":"市の外: the outskirts.","grammar:1643:ex4:trans":"The airport is a busy place.","grammar:1643:ex4:structure":"〜は忙しい場所です","grammar:1643:ex4:words:0:zh":"airport","grammar:1643:ex4:words:0:note":"くうこう","grammar:1643:ex4:words:0:pos":"noun","grammar:1643:ex4:words:1:zh":"(topic)","grammar:1643:ex4:words:1:pos":"particle","grammar:1643:ex4:words:2:zh":"busy","grammar:1643:ex4:words:2:note":"いそがしい","grammar:1643:ex4:words:2:pos":"adjective","grammar:1643:ex4:words:3:zh":"place","grammar:1643:ex4:words:3:note":"ばしょ","grammar:1643:ex4:words:3:pos":"noun","grammar:1643:ex4:words:4:zh":"is","grammar:1643:ex4:words:4:pos":"copula","grammar:1643:ex4:points:0":"❗忙しい場所: a busy place; 空港 = airport.","grammar:1643:ex4:points:1":"忙しい場所: a busy spot.","grammar:1643:ex5:trans":"This airport is new and clean.","grammar:1643:ex5:structure":"〜は新しくて綺麗です","grammar:1643:ex5:words:0:zh":"this","grammar:1643:ex5:words:0:pos":"pre-noun adjectival","grammar:1643:ex5:words:1:zh":"airport","grammar:1643:ex5:words:1:note":"くうこう","grammar:1643:ex5:words:1:pos":"noun","grammar:1643:ex5:words:2:zh":"(topic)","grammar:1643:ex5:words:2:pos":"particle","grammar:1643:ex5:words:3:zh":"new","grammar:1643:ex5:words:3:note":"あたらしくて","grammar:1643:ex5:words:3:pos":"adjective","grammar:1643:ex5:words:4:zh":"clean","grammar:1643:ex5:words:4:note":"きれい","grammar:1643:ex5:words:4:pos":"na-adjective","grammar:1643:ex5:words:5:zh":"(polite form)","grammar:1643:ex5:words:5:pos":"copula","grammar:1643:ex5:points:0":"❗〜くて: both … and … (新しい → 新しくて, linking two descriptions); 綺麗 = clean.","grammar:1643:ex5:points:1":"新しくて綺麗: new and clean."},"1644":{"example:1644:exzh":"Her recovery was a miracle.","example:1644:exzh2":"A miraculous event occurred.","example:1644:exzh3":"We believe in miracles.","example:1644:exzh4":"Miracles happen sometimes.","example:1644:exzh5":"This work is themed around miracles."},"1645":{"example:1645:exzh":"There is a sea to the east of Japan.","example:1645:exzh2":"Tokyo is located in the east of Japan.","example:1645:exzh3":"He went toward the east.","example:1645:exzh4":"East is the direction of sunrise.","example:1645:exzh5":"An east wind is blowing.","grammar:1645:ex:trans":"There is sea to the east of Japan.","grammar:1645:ex:structure":"〜の東に〜があります","grammar:1645:ex:explain":"This sentence uses the basic existence pattern 「〜に〜があります」. 「日本の東」 uses 「の」 to express the direction “the east of Japan,” followed by 「に」 marking the place where something exists; 「が」 marks the thing that exists, 「海」; and 「あります」 expresses the existence of an inanimate thing. With a direction word like 「東（ひがし）」, 「の」 comes before it to attach the reference point.","grammar:1645:ex:words:0:zh":"Japan","grammar:1645:ex:words:0:note":"にほん","grammar:1645:ex:words:0:pos":"noun","grammar:1645:ex:words:1:zh":"'s","grammar:1645:ex:words:1:pos":"particle","grammar:1645:ex:words:2:zh":"the east","grammar:1645:ex:words:2:note":"ひがし","grammar:1645:ex:words:2:pos":"noun","grammar:1645:ex:words:3:zh":"(location of existence)","grammar:1645:ex:words:3:pos":"particle","grammar:1645:ex:words:4:zh":"sea","grammar:1645:ex:words:4:note":"うみ","grammar:1645:ex:words:4:pos":"noun","grammar:1645:ex:words:5:zh":"(nominative)","grammar:1645:ex:words:5:pos":"particle","grammar:1645:ex:words:6:zh":"there is / are","grammar:1645:ex:words:6:pos":"verb","grammar:1645:ex:points:0":"❗東（ひがし）: east; 日本の東 = the eastern side of Japan.","grammar:1645:ex:points:1":"東: east.","grammar:1645:ex2:trans":"Tokyo is located in the east of Japan.","grammar:1645:ex2:structure":"〜は〜の東に位置しています","grammar:1645:ex2:words:0:zh":"Tokyo","grammar:1645:ex2:words:0:note":"とうきょう","grammar:1645:ex2:words:0:pos":"noun","grammar:1645:ex2:words:1:zh":"(topic)","grammar:1645:ex2:words:1:pos":"particle","grammar:1645:ex2:words:2:zh":"Japan","grammar:1645:ex2:words:2:note":"にほん","grammar:1645:ex2:words:2:pos":"noun","grammar:1645:ex2:words:3:zh":"'s","grammar:1645:ex2:words:3:pos":"particle","grammar:1645:ex2:words:4:zh":"the east","grammar:1645:ex2:words:4:note":"ひがし","grammar:1645:ex2:words:4:pos":"noun","grammar:1645:ex2:words:5:zh":"(location of existence)","grammar:1645:ex2:words:5:pos":"particle","grammar:1645:ex2:words:6:zh":"be located","grammar:1645:ex2:words:6:note":"いちしています","grammar:1645:ex2:words:6:pos":"verb","grammar:1645:ex2:points:0":"❗位置する: to be located; 日本の東に位置 = situated in the east.","grammar:1645:ex2:points:1":"位置する: to be located.","grammar:1645:ex3:trans":"He went toward the east.","grammar:1645:ex3:structure":"〜の方角に行きました","grammar:1645:ex3:words:0:zh":"he","grammar:1645:ex3:words:0:note":"かれ","grammar:1645:ex3:words:0:pos":"pronoun","grammar:1645:ex3:words:1:zh":"(topic)","grammar:1645:ex3:words:1:pos":"particle","grammar:1645:ex3:words:2:zh":"eastward","grammar:1645:ex3:words:2:note":"ひがし","grammar:1645:ex3:words:2:pos":"noun","grammar:1645:ex3:words:3:zh":"'s","grammar:1645:ex3:words:3:pos":"particle","grammar:1645:ex3:words:4:zh":"direction","grammar:1645:ex3:words:4:note":"ほうがく","grammar:1645:ex3:words:4:pos":"noun","grammar:1645:ex3:words:5:zh":"(direction)","grammar:1645:ex3:words:5:pos":"particle","grammar:1645:ex3:words:6:zh":"went","grammar:1645:ex3:words:6:note":"いきました","grammar:1645:ex3:words:6:pos":"verb","grammar:1645:ex3:points:0":"❗東の方角: the eastward direction; 方角 = direction.","grammar:1645:ex3:points:1":"東の方角: toward the east.","grammar:1645:ex4:trans":"The east is the direction of sunrise.","grammar:1645:ex4:structure":"東は〜の方向です","grammar:1645:ex4:words:0:zh":"east","grammar:1645:ex4:words:0:note":"ひがし","grammar:1645:ex4:words:0:pos":"noun","grammar:1645:ex4:words:1:zh":"(topic)","grammar:1645:ex4:words:1:pos":"particle","grammar:1645:ex4:words:2:zh":"sunrise","grammar:1645:ex4:words:2:note":"ひので","grammar:1645:ex4:words:2:pos":"noun","grammar:1645:ex4:words:3:zh":"'s","grammar:1645:ex4:words:3:pos":"particle","grammar:1645:ex4:words:4:zh":"direction","grammar:1645:ex4:words:4:note":"ほうこう","grammar:1645:ex4:words:4:pos":"noun","grammar:1645:ex4:words:5:zh":"is","grammar:1645:ex4:words:5:pos":"copula","grammar:1645:ex4:points:0":"❗日の出: sunrise (日 + 出); 東 = the direction where the sun rises.","grammar:1645:ex4:points:1":"東は日の出: the east is where the sun rises.","grammar:1645:ex5:trans":"The east wind is blowing.","grammar:1645:ex5:structure":"東の風が吹いています","grammar:1645:ex5:words:0:zh":"east","grammar:1645:ex5:words:0:note":"ひがし","grammar:1645:ex5:words:0:pos":"noun","grammar:1645:ex5:words:1:zh":"'s","grammar:1645:ex5:words:1:pos":"particle","grammar:1645:ex5:words:2:zh":"wind","grammar:1645:ex5:words:2:note":"かぜ","grammar:1645:ex5:words:2:pos":"noun","grammar:1645:ex5:words:3:zh":"(nominative)","grammar:1645:ex5:words:3:pos":"particle","grammar:1645:ex5:words:4:zh":"is blowing","grammar:1645:ex5:words:4:note":"ふいています","grammar:1645:ex5:words:4:pos":"verb","grammar:1645:ex5:points:0":"❗東の風: east wind; 風が吹く = the wind blows.","grammar:1645:ex5:points:1":"東の風: east wind.","exam:1645:zh":"The direction where the sun rises in the morning is east.","exam:1645:why":"The sun rises in the 「東」. 「西」 is the direction where the sun sets."},"1646":{"example:1646:exzh":"He fought as a warrior.","example:1646:exzh2":"The warrior is known as a hero.","example:1646:exzh3":"She is a brave warrior.","example:1646:exzh4":"Warriors fight to protect their own country.","example:1646:exzh5":"In the movie, the warriors set out on an adventure."},"1647":{"example:1647:exzh":"Please explain the situation.","example:1647:exzh2":"He knows the situation.","example:1647:exzh3":"The situation has changed a little.","example:1647:exzh4":"It's hard to understand the situation.","example:1647:exzh5":"We need to get the situation in order."},"1648":{"example:1648:exzh":"I call you my lord.","example:1648:exzh2":"What line of work are you in, my lord?","example:1648:exzh3":"I'd like to hear your opinion, my lord.","example:1648:exzh4":"My lord, I'm on my way.","example:1648:exzh5":"You are a friend I can trust, my lord."},"1649":{"example:1649:exzh":"It will probably rain tomorrow.","example:1649:exzh2":"He will probably be late.","example:1649:exzh3":"I think that movie will probably be interesting.","example:1649:exzh4":"It will probably get cold tonight.","example:1649:exzh5":"You probably don't like this problem."},"1650":{"example:1650:exzh":"This food is delicious.","example:1650:exzh2":"We're going to buy food.","example:1650:exzh3":"Please store the food so it doesn't spoil.","example:1650:exzh4":"What food do you like?","example:1650:exzh5":"Food reflects culture.","grammar:1650:ex:trans":"This food is delicious.","grammar:1650:ex:structure":"〜は美味しいです","grammar:1650:ex:explain":"「食べ物」 is formed from the continuative form of the verb 「食べる」 plus 「物」 and means “food”; this “verb continuative + 物” combination is a common way of building words. 「は」 brings up 「この食べ物」 as the topic, and the predicate uses the i-adjective 「美味しい」 plus the polite 「です」 to say that it's delicious. 「美味しい」 is read 「おいしい」.","grammar:1650:ex:words:0:zh":"this","grammar:1650:ex:words:0:pos":"pre-noun adjectival","grammar:1650:ex:words:1:zh":"food","grammar:1650:ex:words:1:note":"たべもの","grammar:1650:ex:words:1:pos":"noun","grammar:1650:ex:words:2:zh":"(topic)","grammar:1650:ex:words:2:pos":"particle","grammar:1650:ex:words:3:zh":"delicious","grammar:1650:ex:words:3:note":"おいしい","grammar:1650:ex:words:3:pos":"adjective","grammar:1650:ex:words:4:zh":"(polite form)","grammar:1650:ex:words:4:pos":"copula","grammar:1650:ex:points:0":"❗食べ物（たべもの）: food (食べる + 物); 美味しい = delicious.","grammar:1650:ex:points:1":"食べ物: food.","grammar:1650:ex2:trans":"We're going to buy food.","grammar:1650:ex2:structure":"〜を買いに行きます","grammar:1650:ex2:words:0:zh":"food","grammar:1650:ex2:words:0:note":"たべもの","grammar:1650:ex2:words:0:pos":"noun","grammar:1650:ex2:words:1:zh":"(object marker)","grammar:1650:ex2:words:1:pos":"particle","grammar:1650:ex2:words:2:zh":"buy","grammar:1650:ex2:words:2:note":"かい","grammar:1650:ex2:words:2:pos":"verb","grammar:1650:ex2:words:3:zh":"(purpose)","grammar:1650:ex2:words:3:pos":"particle","grammar:1650:ex2:words:4:zh":"go","grammar:1650:ex2:words:4:note":"いきます","grammar:1650:ex2:words:4:pos":"verb","grammar:1650:ex2:points:0":"❗〜を買いに行く: to go buy … (masu-form of the verb + に).","grammar:1650:ex2:points:1":"買いに行く: to go buy.","grammar:1650:ex3:trans":"Please store the food so that it doesn't spoil.","grammar:1650:ex3:structure":"食べ物 + は + 腐らないように + 保存してください","grammar:1650:ex3:words:0:zh":"food","grammar:1650:ex3:words:0:note":"たべもの","grammar:1650:ex3:words:0:pos":"noun","grammar:1650:ex3:words:1:zh":"marks the topic","grammar:1650:ex3:words:1:pos":"particle","grammar:1650:ex3:words:2:zh":"doesn't spoil","grammar:1650:ex3:words:2:note":"くさらない; the nai-form of 腐る","grammar:1650:ex3:words:2:pos":"verb","grammar:1650:ex3:words:3:zh":"so that (it doesn't); in order to","grammar:1650:ex3:words:3:pos":"Phrase","grammar:1650:ex3:words:4:zh":"preservation","grammar:1650:ex3:words:4:note":"ほぞんして; the te-form of 保存する","grammar:1650:ex3:words:4:pos":"verb","grammar:1650:ex3:words:5:zh":"please","grammar:1650:ex3:words:5:pos":"auxiliary verb","grammar:1650:ex3:points:0":"「食べ物は」 brings the food up as the topic, and the rest explains what to do with it.","grammar:1650:ex3:points:1":"「nai-form + ように」 means “so that … doesn't happen”: 「腐らないように」 = so that it doesn't spoil.","grammar:1650:ex3:points:2":"「保存してください」 is the te-form plus 「ください」, politely asking someone to do something.","grammar:1650:ex4:trans":"What food do you like?","grammar:1650:ex4:structure":"好きな食べ物は何ですか","grammar:1650:ex4:words:0:zh":"you","grammar:1650:ex4:words:0:pos":"pronoun","grammar:1650:ex4:words:1:zh":"'s","grammar:1650:ex4:words:1:pos":"particle","grammar:1650:ex4:words:2:zh":"to like","grammar:1650:ex4:words:2:note":"すき","grammar:1650:ex4:words:2:pos":"na-adjective","grammar:1650:ex4:words:3:zh":"(attributive form)","grammar:1650:ex4:words:3:pos":"auxiliary verb","grammar:1650:ex4:words:4:zh":"food","grammar:1650:ex4:words:4:note":"たべもの","grammar:1650:ex4:words:4:pos":"noun","grammar:1650:ex4:words:5:zh":"(topic)","grammar:1650:ex4:words:5:pos":"particle","grammar:1650:ex4:words:6:zh":"what","grammar:1650:ex4:words:6:note":"なに","grammar:1650:ex4:words:6:pos":"pronoun","grammar:1650:ex4:words:7:zh":"is","grammar:1650:ex4:words:7:pos":"copula","grammar:1650:ex4:words:8:zh":"(question)","grammar:1650:ex4:words:8:pos":"particle","grammar:1650:ex4:points:0":"❗好きな食べ物: food you like; 何ですか = what is it?","grammar:1650:ex4:points:1":"好きな食べ物: the food you like.","grammar:1650:ex5:trans":"Food reflects culture.","grammar:1650:ex5:structure":"〜は〜を反映しています","grammar:1650:ex5:words:0:zh":"food","grammar:1650:ex5:words:0:note":"たべもの","grammar:1650:ex5:words:0:pos":"noun","grammar:1650:ex5:words:1:zh":"(topic)","grammar:1650:ex5:words:1:pos":"particle","grammar:1650:ex5:words:2:zh":"culture","grammar:1650:ex5:words:2:note":"ぶんか","grammar:1650:ex5:words:2:pos":"noun","grammar:1650:ex5:words:3:zh":"(object marker)","grammar:1650:ex5:words:3:pos":"particle","grammar:1650:ex5:words:4:zh":"reflect","grammar:1650:ex5:words:4:note":"はんえいしています","grammar:1650:ex5:words:4:pos":"verb","grammar:1650:ex5:points:0":"❗反映する: to reflect, to mirror; 食べ物が文化を反映 = food reflects culture.","grammar:1650:ex5:points:1":"反映する: to reflect.","exam:1650:zh":"Please put food like rice and bread in this bag, and water and juice in that bag.","exam:1650:why":"「食べ物」 is the general term for things you can eat, like rice and bread. 「果物」 refers only to fruit and can't include rice and bread."},"1651":{"example:1651:exzh":"He has graduated from university.","example:1651:exzh2":"The graduation ceremony will be held next week.","example:1651:exzh3":"I want to graduate from high school.","example:1651:exzh4":"I'm making plans for after graduation.","example:1651:exzh5":"Graduates will carve out a new future.","grammar:1651:ex:trans":"He graduated from university.","grammar:1651:ex:structure":"〜を卒業しました","grammar:1651:ex:explain":"The key is 「〜を卒業する」 = “to graduate from ….” Here 「を」 does not mark an ordinary object; it marks the starting point you leave or the place you depart from, just as in 「大学を出る」 = “to leave university.” 「卒業（そつぎょう）する」 is a suru-verb, and 「卒業しました」 is its polite past form. 「は」 brings up 「彼」 as the topic.","grammar:1651:ex:words:0:zh":"he","grammar:1651:ex:words:0:note":"かれ","grammar:1651:ex:words:0:pos":"pronoun","grammar:1651:ex:words:1:zh":"(topic)","grammar:1651:ex:words:1:pos":"particle","grammar:1651:ex:words:2:zh":"university","grammar:1651:ex:words:2:note":"だいがく","grammar:1651:ex:words:2:pos":"noun","grammar:1651:ex:words:3:zh":"(starting point)","grammar:1651:ex:words:3:pos":"particle","grammar:1651:ex:words:4:zh":"graduated","grammar:1651:ex:words:4:note":"そつぎょうしました","grammar:1651:ex:words:4:pos":"verb","grammar:1651:ex:points:0":"❗卒業（そつぎょう）する: to graduate; 「〜を卒業する」 = to graduate from … (を marks the school you leave).","grammar:1651:ex:points:1":"卒業する: to graduate.","grammar:1651:ex2:trans":"The graduation ceremony will be held next week.","grammar:1651:ex2:structure":"〜は来週行われる","grammar:1651:ex2:words:0:zh":"graduation ceremony","grammar:1651:ex2:words:0:note":"そつぎょうしき","grammar:1651:ex2:words:0:pos":"noun","grammar:1651:ex2:words:1:zh":"(topic)","grammar:1651:ex2:words:1:pos":"particle","grammar:1651:ex2:words:2:zh":"next week","grammar:1651:ex2:words:2:note":"らいしゅう","grammar:1651:ex2:words:2:pos":"noun","grammar:1651:ex2:words:3:zh":"held","grammar:1651:ex2:words:3:note":"おこなわれる","grammar:1651:ex2:words:3:pos":"verb","grammar:1651:ex2:points:0":"❗卒業式: graduation ceremony (卒業 + 式); 行われる = to be held (passive).","grammar:1651:ex2:points:1":"卒業式: graduation ceremony.","grammar:1651:ex3:trans":"I want to graduate from high school.","grammar:1651:ex3:structure":"〜を卒業したい","grammar:1651:ex3:words:0:zh":"I","grammar:1651:ex3:words:0:note":"わたし","grammar:1651:ex3:words:0:pos":"pronoun","grammar:1651:ex3:words:1:zh":"(topic)","grammar:1651:ex3:words:1:pos":"particle","grammar:1651:ex3:words:2:zh":"high school","grammar:1651:ex3:words:2:note":"こうこう","grammar:1651:ex3:words:2:pos":"noun","grammar:1651:ex3:words:3:zh":"(starting point)","grammar:1651:ex3:words:3:pos":"particle","grammar:1651:ex3:words:4:zh":"want to graduate","grammar:1651:ex3:words:4:note":"そつぎょうしたい","grammar:1651:ex3:words:4:pos":"verb","grammar:1651:ex3:points:0":"❗高校を卒業する: to graduate from high school; 〜たい = want to ….","grammar:1651:ex3:points:1":"高校を卒業: to graduate from high school.","grammar:1651:ex4:trans":"I'm making plans for after graduation.","grammar:1651:ex4:structure":"卒業後の計画を立てています","grammar:1651:ex4:words:0:zh":"graduation","grammar:1651:ex4:words:0:note":"そつぎょう","grammar:1651:ex4:words:0:pos":"noun","grammar:1651:ex4:words:1:zh":"later, afterwards","grammar:1651:ex4:words:1:note":"ご","grammar:1651:ex4:words:1:pos":"noun","grammar:1651:ex4:words:2:zh":"'s","grammar:1651:ex4:words:2:pos":"particle","grammar:1651:ex4:words:3:zh":"plans","grammar:1651:ex4:words:3:note":"けいかく","grammar:1651:ex4:words:3:pos":"noun","grammar:1651:ex4:words:4:zh":"(object marker)","grammar:1651:ex4:words:4:pos":"particle","grammar:1651:ex4:words:5:zh":"is drawing up","grammar:1651:ex4:words:5:note":"たてています","grammar:1651:ex4:words:5:pos":"verb","grammar:1651:ex4:points:0":"❗卒業後: after graduation (卒業 + 後); 計画を立てる = to make a plan.","grammar:1651:ex4:points:1":"卒業後: after graduation.","grammar:1651:ex5:trans":"Graduates will carve out a new future.","grammar:1651:ex5:structure":"〜を切り開きます","grammar:1651:ex5:words:0:zh":"graduates","grammar:1651:ex5:words:0:note":"そつぎょうせい","grammar:1651:ex5:words:0:pos":"noun","grammar:1651:ex5:words:1:zh":"(topic)","grammar:1651:ex5:words:1:pos":"particle","grammar:1651:ex5:words:2:zh":"new","grammar:1651:ex5:words:2:note":"あたらしい","grammar:1651:ex5:words:2:pos":"adjective","grammar:1651:ex5:words:3:zh":"the future","grammar:1651:ex5:words:3:note":"みらい","grammar:1651:ex5:words:3:pos":"noun","grammar:1651:ex5:words:4:zh":"(object marker)","grammar:1651:ex5:words:4:pos":"particle","grammar:1651:ex5:words:5:zh":"carve out","grammar:1651:ex5:words:5:note":"きりひらきます","grammar:1651:ex5:words:5:pos":"verb","grammar:1651:ex5:points:0":"❗卒業生: graduate (卒業 + 生); 切り開く = to carve out, to open up.","grammar:1651:ex5:points:1":"切り開く: to carve out."},"1652":{"example:1652:exzh":"This area has many tourist spots.","example:1652:exzh2":"Learning about the local culture is important.","example:1652:exzh3":"Each region has its own specialty products.","example:1652:exzh4":"Let's mingle with the local people.","example:1652:exzh5":"This region is rich in nature."},"1653":{"example:1653:exzh":"He is a colonel in the army.","example:1653:exzh2":"The colonel is commanding the troops.","example:1653:exzh3":"The main character of this movie is a colonel.","example:1653:exzh4":"I will obey the colonel's orders.","example:1653:exzh5":"I will fulfill my duties as a colonel."},"1654":{"example:1654:exzh":"Eric is my friend.","example:1654:exzh2":"He is called Eric.","example:1654:exzh3":"Eric is good at soccer.","example:1654:exzh4":"Have you ever met Eric?","example:1654:exzh5":"Eric is studying English."},"1655":{"example:1655:exzh":"This tree is short.","example:1655:exzh2":"His voice is deep.","example:1655:exzh3":"It's in a low position.","example:1655:exzh4":"She is wearing low-heeled shoes.","example:1655:exzh5":"I like talking in a low voice.","grammar:1655:ex:trans":"This tree is short.","grammar:1655:ex:structure":"〜は低いです","grammar:1655:ex:explain":"「低い」 is read 「ひくい」 and is an i-adjective meaning 'low' or 'short'; it can also describe a deep, low voice, and its opposite is 「高い」. In this sentence it works as the predicate followed by です (polite form). 「は」 introduces the topic 「この木」. Note that 「低い」 differs from 「短い（みじかい）」: the former refers to height, the latter to length.","grammar:1655:ex:words:0:zh":"this","grammar:1655:ex:words:0:pos":"pre-noun adjectival","grammar:1655:ex:words:1:zh":"tree","grammar:1655:ex:words:1:note":"き","grammar:1655:ex:words:1:pos":"noun","grammar:1655:ex:words:2:zh":"(topic)","grammar:1655:ex:words:2:pos":"particle","grammar:1655:ex:words:3:zh":"short","grammar:1655:ex:words:3:note":"ひくい","grammar:1655:ex:words:3:pos":"adjective","grammar:1655:ex:words:4:zh":"(polite form)","grammar:1655:ex:words:4:pos":"copula","grammar:1655:ex:points:0":"❗低い（ひくい）: low, short, (of a voice) deep; vs 高い (high).","grammar:1655:ex:points:1":"低い: low / short.","grammar:1655:ex2:trans":"His voice is deep.","grammar:1655:ex2:structure":"〜の声は低い","grammar:1655:ex2:words:0:zh":"he","grammar:1655:ex2:words:0:note":"かれ","grammar:1655:ex2:words:0:pos":"pronoun","grammar:1655:ex2:words:1:zh":"'s","grammar:1655:ex2:words:1:pos":"particle","grammar:1655:ex2:words:2:zh":"voice","grammar:1655:ex2:words:2:note":"こえ","grammar:1655:ex2:words:2:pos":"noun","grammar:1655:ex2:words:3:zh":"(topic)","grammar:1655:ex2:words:3:pos":"particle","grammar:1655:ex2:words:4:zh":"deep (of a voice)","grammar:1655:ex2:words:4:note":"ひくい","grammar:1655:ex2:words:4:pos":"adjective","grammar:1655:ex2:points:0":"❗声が低い: to have a deep voice; 低い = low.","grammar:1655:ex2:points:1":"声が低い: deep (voice).","grammar:1655:ex3:trans":"It is in a low position.","grammar:1655:ex3:structure":"低い位置にあります","grammar:1655:ex3:words:0:zh":"low","grammar:1655:ex3:words:0:note":"ひくい","grammar:1655:ex3:words:0:pos":"adjective","grammar:1655:ex3:words:1:zh":"location","grammar:1655:ex3:words:1:note":"いち","grammar:1655:ex3:words:1:pos":"noun","grammar:1655:ex3:words:2:zh":"(location of existence)","grammar:1655:ex3:words:2:pos":"particle","grammar:1655:ex3:words:3:zh":"there is / are","grammar:1655:ex3:words:3:pos":"verb","grammar:1655:ex3:points:0":"❗低い位置: a low place; 位置 = position.","grammar:1655:ex3:points:1":"低い位置: a low place.","grammar:1655:ex4:trans":"She is wearing low-heeled shoes.","grammar:1655:ex4:structure":"〜の低い〜を履いています","grammar:1655:ex4:words:0:zh":"she","grammar:1655:ex4:words:0:note":"かのじょ","grammar:1655:ex4:words:0:pos":"pronoun","grammar:1655:ex4:words:1:zh":"(topic)","grammar:1655:ex4:words:1:pos":"particle","grammar:1655:ex4:words:2:zh":"heel","grammar:1655:ex4:words:2:pos":"noun","grammar:1655:ex4:words:3:zh":"(the subject inside the modifier)","grammar:1655:ex4:words:3:pos":"particle","grammar:1655:ex4:words:4:zh":"low","grammar:1655:ex4:words:4:note":"ひくい","grammar:1655:ex4:words:4:pos":"adjective","grammar:1655:ex4:words:5:zh":"shoes","grammar:1655:ex4:words:5:note":"くつ","grammar:1655:ex4:words:5:pos":"noun","grammar:1655:ex4:words:6:zh":"(object marker)","grammar:1655:ex4:words:6:pos":"particle","grammar:1655:ex4:words:7:zh":"wear (shoes)","grammar:1655:ex4:words:7:note":"はいて; the te-form of 履く","grammar:1655:ex4:words:7:pos":"verb","grammar:1655:ex4:words:8:zh":"(a state)","grammar:1655:ex4:words:8:pos":"auxiliary verb","grammar:1655:ex4:points:0":"❗ヒールの低い靴: shoes with low heels — 「低い」 refers to height; for a short skirt you would use 「短い」.","grammar:1655:ex4:points:1":"In a noun-modifying clause, the 「が」 of 「ヒールが低い」 can be replaced with 「の」.","grammar:1655:ex4:points:2":"For things worn on the lower body, such as shoes, pants, and skirts, use 「履く」.","grammar:1655:ex5:trans":"I like talking in a low voice.","grammar:1655:ex5:structure":"低い声で話すのが好きです","grammar:1655:ex5:words:0:zh":"deep (of a voice)","grammar:1655:ex5:words:0:note":"ひくい","grammar:1655:ex5:words:0:pos":"adjective","grammar:1655:ex5:words:1:zh":"voice","grammar:1655:ex5:words:1:note":"こえ","grammar:1655:ex5:words:1:pos":"noun","grammar:1655:ex5:words:2:zh":"(means)","grammar:1655:ex5:words:2:pos":"particle","grammar:1655:ex5:words:3:zh":"talk","grammar:1655:ex5:words:3:note":"はなす","grammar:1655:ex5:words:3:pos":"verb","grammar:1655:ex5:words:4:zh":"(nominalizer)","grammar:1655:ex5:words:4:pos":"particle","grammar:1655:ex5:words:5:zh":"(object)","grammar:1655:ex5:words:5:pos":"particle","grammar:1655:ex5:words:6:zh":"to like","grammar:1655:ex5:words:6:note":"すき","grammar:1655:ex5:words:6:pos":"na-adjective","grammar:1655:ex5:words:7:zh":"(polite form)","grammar:1655:ex5:words:7:pos":"copula","grammar:1655:ex5:points:0":"❗低い声で: in a low voice (で marks the means).","grammar:1655:ex5:points:1":"低い声で: in a low voice.","exam:1655:zh":"This chair is only twenty centimeters high, which is too low for an adult to sit on.","exam:1655:why":"To say the chair's height is not enough, use 「低い」. 「短い」 describes a short length, not low height."},"1656":{"example:1656:exzh":"I bought a large amount of fruit.","example:1656:exzh2":"This shop specializes in selling in bulk.","example:1656:exzh3":"We printed a large number of flyers for the event.","example:1656:exzh4":"Drinking plenty of water is good for your health.","example:1656:exzh5":"This product can be bought in bulk."},"1657":{"example:1657:exzh":"Working adults have many obligations.","example:1657:exzh2":"Fulfilling your obligations is important.","example:1657:exzh3":"This job comes with obligations.","example:1657:exzh4":"Compulsory education is necessary for every child.","example:1657:exzh5":"He has obligations to his family."},"1658":{"example:1658:exzh":"I lost sight of him.","example:1658:exzh2":"Don't lose sight of an important opportunity.","example:1658:exzh3":"I lost sight of a friend on the street.","example:1658:exzh4":"She has lost sight of her goal.","example:1658:exzh5":"It's common to lose sight of something."},"1659":{"example:1659:exzh":"Goodbye, until the day we meet again.","example:1659:exzh2":"Goodbye, have a good weekend!","example:1659:exzh3":"She said goodbye.","example:1659:exzh4":"We shook hands in farewell.","example:1659:exzh5":"Goodbye, friend.","grammar:1659:ex:trans":"Goodbye, until we meet again.","grammar:1659:ex:structure":"〜まで、さようなら","grammar:1659:ex:explain":"「さようなら」 is a somewhat formal farewell that suggests a long parting; in everyday speech friends usually say 「じゃあね／またね」. In the first half, 「また会う日まで」 uses the plain form of the verb 「また会う」 to modify the noun 「日」, then adds 「まで」 ('until'), giving 'until the day we meet again'. The whole line is a formal, emotional goodbye.","grammar:1659:ex:words:0:zh":"again","grammar:1659:ex:words:0:pos":"adverb","grammar:1659:ex:words:1:zh":"meet","grammar:1659:ex:words:1:note":"あう","grammar:1659:ex:words:1:pos":"verb","grammar:1659:ex:words:2:zh":"day","grammar:1659:ex:words:2:note":"ひ","grammar:1659:ex:words:2:pos":"noun","grammar:1659:ex:words:3:zh":"until","grammar:1659:ex:words:3:pos":"particle","grammar:1659:ex:words:4:zh":"goodbye","grammar:1659:ex:words:4:pos":"interjection","grammar:1659:ex:points:0":"❗さようなら: goodbye (a fairly formal farewell suggesting a long parting; in everyday speech friends usually say 「じゃあね／またね」).","grammar:1659:ex:points:1":"さようなら: farewell.","grammar:1659:ex2:trans":"Goodbye, have a nice weekend!","grammar:1659:ex2:structure":"さようなら、良い週末を","grammar:1659:ex2:words:0:zh":"goodbye","grammar:1659:ex2:words:0:pos":"interjection","grammar:1659:ex2:words:1:zh":"good","grammar:1659:ex2:words:1:note":"よい","grammar:1659:ex2:words:1:pos":"adjective","grammar:1659:ex2:words:2:zh":"weekend","grammar:1659:ex2:words:2:note":"しゅうまつ","grammar:1659:ex2:words:2:pos":"noun","grammar:1659:ex2:words:3:zh":"(object marker)","grammar:1659:ex2:words:3:pos":"particle","grammar:1659:ex2:points:0":"❗良い週末を (short for 過ごしてね): have a good weekend (a set parting phrase).","grammar:1659:ex2:points:1":"良い週末を: have a good weekend.","grammar:1659:ex3:trans":"She said goodbye.","grammar:1659:ex3:structure":"さようならと言った","grammar:1659:ex3:words:0:zh":"she","grammar:1659:ex3:words:0:note":"かのじょ","grammar:1659:ex3:words:0:pos":"pronoun","grammar:1659:ex3:words:1:zh":"(topic)","grammar:1659:ex3:words:1:pos":"particle","grammar:1659:ex3:words:2:zh":"goodbye","grammar:1659:ex3:words:2:pos":"interjection","grammar:1659:ex3:words:3:zh":"(quotation)","grammar:1659:ex3:words:3:pos":"particle","grammar:1659:ex3:words:4:zh":"said","grammar:1659:ex3:words:4:note":"いった","grammar:1659:ex3:words:4:pos":"verb","grammar:1659:ex3:points:0":"❗〜と言う: to say …; さようならと言う = to say goodbye.","grammar:1659:ex3:points:1":"さようならと言う: to say goodbye.","grammar:1659:ex4:trans":"We shook hands and said goodbye.","grammar:1659:ex4:structure":"さようならと握手した","grammar:1659:ex4:words:0:zh":"goodbye","grammar:1659:ex4:words:0:pos":"interjection","grammar:1659:ex4:words:1:zh":"(quotation)","grammar:1659:ex4:words:1:pos":"particle","grammar:1659:ex4:words:2:zh":"shook hands","grammar:1659:ex4:words:2:note":"あくしゅした","grammar:1659:ex4:words:2:pos":"verb","grammar:1659:ex4:points:0":"❗握手する: to shake hands; さようならと握手 = to shake hands in farewell.","grammar:1659:ex4:points:1":"握手する: to shake hands.","grammar:1659:ex5:trans":"Goodbye, friend.","grammar:1659:ex5:structure":"さようなら、友達","grammar:1659:ex5:words:0:zh":"goodbye","grammar:1659:ex5:words:0:pos":"interjection","grammar:1659:ex5:words:1:zh":"friend","grammar:1659:ex5:words:1:note":"ともだち","grammar:1659:ex5:words:1:pos":"noun","grammar:1659:ex5:points:0":"❗さようなら、友達: goodbye, friend (an emotional farewell).","grammar:1659:ex5:points:1":"さようなら: goodbye.","exam:1659:zh":"When class ended and I left school, I said goodbye to my teacher.","exam:1659:why":"「さようなら」 is used for farewells and fits leaving school. 「おはよう」 is a greeting for meeting someone in the morning."},"1660":{"example:1660:exzh":"I'm studying English.","example:1660:exzh2":"It's convenient to be able to speak English.","example:1660:exzh3":"He is good at English.","example:1660:exzh4":"English class is fun.","example:1660:exzh5":"Writing English is difficult.","grammar:1660:ex:trans":"I am studying English.","grammar:1660:ex:structure":"〜を勉強しています","grammar:1660:ex:explain":"This is the 「〜を勉強しています」 pattern, where 「を」 marks what is being studied, 「英語」. 「勉強しています」 is the 「〜ている」 form of 「勉強する」, which can mean either that something is happening right now or that it has been going on over the long term. 「は」 introduces the topic 「私」. 「英語」 is read 「えいご」.","grammar:1660:ex:words:0:zh":"I","grammar:1660:ex:words:0:note":"わたし","grammar:1660:ex:words:0:pos":"pronoun","grammar:1660:ex:words:1:zh":"(topic)","grammar:1660:ex:words:1:pos":"particle","grammar:1660:ex:words:2:zh":"English","grammar:1660:ex:words:2:note":"えいご","grammar:1660:ex:words:2:pos":"noun","grammar:1660:ex:words:3:zh":"(object marker)","grammar:1660:ex:words:3:pos":"particle","grammar:1660:ex:words:4:zh":"has been studying","grammar:1660:ex:words:4:note":"べんきょうしています","grammar:1660:ex:words:4:pos":"verb","grammar:1660:ex:points:0":"❗英語（えいご）: English; 英語を勉強する = to study English.","grammar:1660:ex:points:1":"英語: English.","grammar:1660:ex2:trans":"Being able to speak English is convenient.","grammar:1660:ex2:structure":"〜が話せると便利です","grammar:1660:ex2:words:0:zh":"English","grammar:1660:ex2:words:0:note":"えいご","grammar:1660:ex2:words:0:pos":"noun","grammar:1660:ex2:words:1:zh":"(object)","grammar:1660:ex2:words:1:pos":"particle","grammar:1660:ex2:words:2:zh":"can speak","grammar:1660:ex2:words:2:note":"はなせる","grammar:1660:ex2:words:2:pos":"verb","grammar:1660:ex2:words:3:zh":"(as soon as…)","grammar:1660:ex2:words:3:pos":"particle","grammar:1660:ex2:words:4:zh":"convenient","grammar:1660:ex2:words:4:note":"べんり","grammar:1660:ex2:words:4:pos":"na-adjective","grammar:1660:ex2:words:5:zh":"(polite form)","grammar:1660:ex2:words:5:pos":"copula","grammar:1660:ex2:points:0":"❗話せる: to be able to speak (the potential form of 話す); 〜と便利 = it is convenient if …","grammar:1660:ex2:points:1":"英語が話せる: to be able to speak English.","grammar:1660:ex3:trans":"He is good at English.","grammar:1660:ex3:structure":"〜が得意です","grammar:1660:ex3:words:0:zh":"he","grammar:1660:ex3:words:0:note":"かれ","grammar:1660:ex3:words:0:pos":"pronoun","grammar:1660:ex3:words:1:zh":"(topic)","grammar:1660:ex3:words:1:pos":"particle","grammar:1660:ex3:words:2:zh":"English","grammar:1660:ex3:words:2:note":"えいご","grammar:1660:ex3:words:2:pos":"noun","grammar:1660:ex3:words:3:zh":"(object)","grammar:1660:ex3:words:3:pos":"particle","grammar:1660:ex3:words:4:zh":"good at","grammar:1660:ex3:words:4:note":"とくい","grammar:1660:ex3:words:4:pos":"na-adjective","grammar:1660:ex3:words:5:zh":"(polite form)","grammar:1660:ex3:words:5:pos":"copula","grammar:1660:ex3:points:0":"❗英語が得意: good at English; 〜が得意 = to be good at …","grammar:1660:ex3:points:1":"英語が得意: good at English.","grammar:1660:ex4:trans":"English class is fun.","grammar:1660:ex4:structure":"〜の授業は楽しいです","grammar:1660:ex4:words:0:zh":"English","grammar:1660:ex4:words:0:note":"えいご","grammar:1660:ex4:words:0:pos":"noun","grammar:1660:ex4:words:1:zh":"'s","grammar:1660:ex4:words:1:pos":"particle","grammar:1660:ex4:words:2:zh":"class","grammar:1660:ex4:words:2:note":"じゅぎょう","grammar:1660:ex4:words:2:pos":"noun","grammar:1660:ex4:words:3:zh":"(topic)","grammar:1660:ex4:words:3:pos":"particle","grammar:1660:ex4:words:4:zh":"interesting","grammar:1660:ex4:words:4:note":"たのしい","grammar:1660:ex4:words:4:pos":"adjective","grammar:1660:ex4:words:5:zh":"(polite form)","grammar:1660:ex4:words:5:pos":"copula","grammar:1660:ex4:points:0":"❗英語の授業: English class; 授業 = class, lesson.","grammar:1660:ex4:points:1":"英語の授業: English class.","grammar:1660:ex5:trans":"Writing English is difficult.","grammar:1660:ex5:structure":"〜を書くのが難しいです","grammar:1660:ex5:words:0:zh":"English","grammar:1660:ex5:words:0:note":"えいご","grammar:1660:ex5:words:0:pos":"noun","grammar:1660:ex5:words:1:zh":"(object marker)","grammar:1660:ex5:words:1:pos":"particle","grammar:1660:ex5:words:2:zh":"write","grammar:1660:ex5:words:2:note":"かく","grammar:1660:ex5:words:2:pos":"verb","grammar:1660:ex5:words:3:zh":"(nominalizer)","grammar:1660:ex5:words:3:pos":"particle","grammar:1660:ex5:words:4:zh":"(nominative)","grammar:1660:ex5:words:4:pos":"particle","grammar:1660:ex5:words:5:zh":"difficult","grammar:1660:ex5:words:5:note":"むずかしい","grammar:1660:ex5:words:5:pos":"adjective","grammar:1660:ex5:words:6:zh":"(polite form)","grammar:1660:ex5:words:6:pos":"copula","grammar:1660:ex5:points:0":"❗英語を書く: to write English; 〜のが難しい = it is hard to …","grammar:1660:ex5:points:1":"英語を書く: to write English.","exam:1660:zh":"「Good morning」 is used when greeting someone in the morning in English.","exam:1660:why":"「Good morning」 is the English morning greeting. The 「日本語」 morning greeting is 「おはようございます」."},"1661":{"example:1661:exzh":"We travel by van.","example:1661:exzh2":"Driving a van is fun.","example:1661:exzh3":"My mom drives a van.","example:1661:exzh4":"I bought a new van.","example:1661:exzh5":"I go out with friends in a van."},"1662":{"example:1662:exzh":"He guessed the answer right away.","example:1662:exzh2":"Please try to guess the answer to this question.","example:1662:exzh3":"I like guessing the outcome of a match.","example:1662:exzh4":"She won the lottery.","example:1662:exzh5":"It's difficult to guess right."},"1663":{"example:1663:exzh":"He is a musical genius.","example:1663:exzh2":"Even geniuses need effort.","example:1663:exzh3":"She is a genius at drawing.","example:1663:exzh4":"Geniuses are sometimes not understood.","example:1663:exzh5":"Many geniuses have left their names in history."},"1664":{"example:1664:exzh":"He is an ambassador of Japan.","example:1664:exzh2":"Work at the embassy is important.","example:1664:exzh3":"She will meet with ambassadors from various countries.","example:1664:exzh4":"The ambassador seeks cooperation.","example:1664:exzh5":"The ambassador returns home at the end of the term."},"1665":{"example:1665:exzh":"Please store this.","example:1665:exzh2":"Safekeeping of items is important.","example:1665:exzh3":"Files need to be stored properly.","example:1665:exzh4":"Valuables are kept in a safe.","example:1665:exzh5":"I'm thinking about how to store the data."},"1666":{"example:1666:exzh":"I'm counting on my fingers.","example:1666:exzh2":"I have to count the money.","example:1666:exzh3":"He counted the number of cars.","example:1666:exzh4":"The children are counting things.","example:1666:exzh5":"I raised my hand in class and counted.","grammar:1666:ex:trans":"I'm counting on my fingers.","grammar:1666:ex:structure":"〜を使って数えています","grammar:1666:ex:explain":"In 「指を使って数えています」, 「を」 marks 「指」 as the object of 「使う」, and 「使って」 is the te-form, meaning by using fingers as the means for the action that follows; this kind of te-form connection can show method. The following 「数えています」 is the 「〜ている」 form of 「数える」(かぞえる) = to count, showing that counting is in progress.","grammar:1666:ex:words:0:zh":"fingers","grammar:1666:ex:words:0:note":"ゆび","grammar:1666:ex:words:0:pos":"noun","grammar:1666:ex:words:1:zh":"(object marker)","grammar:1666:ex:words:1:pos":"particle","grammar:1666:ex:words:2:zh":"use","grammar:1666:ex:words:2:note":"つかって","grammar:1666:ex:words:2:pos":"verb","grammar:1666:ex:words:3:zh":"counting","grammar:1666:ex:words:3:note":"かぞえています","grammar:1666:ex:words:3:pos":"verb","grammar:1666:ex:points:0":"❗数える (かぞえる): to count.","grammar:1666:ex:points:1":"指を使って: using fingers.","grammar:1666:ex2:trans":"I have to count money.","grammar:1666:ex2:structure":"〜を〜なければなりません","grammar:1666:ex2:words:0:zh":"money","grammar:1666:ex2:words:0:note":"おかね","grammar:1666:ex2:words:0:pos":"noun","grammar:1666:ex2:words:1:zh":"(object marker)","grammar:1666:ex2:words:1:pos":"particle","grammar:1666:ex2:words:2:zh":"must count","grammar:1666:ex2:words:2:note":"かぞえなければなりません","grammar:1666:ex2:words:2:pos":"verb","grammar:1666:ex2:points:0":"お金を数える: to count money.","grammar:1666:ex2:points:1":"〜なければなりません: must …","grammar:1666:ex3:trans":"He counted the number of cars.","grammar:1666:ex3:structure":"〜は〜の数を数えました","grammar:1666:ex3:explain":"「彼は」 presents the person doing it, and 「車の数」 means the number of cars. 「を」 marks the object being counted, and 「数えました」 is the polite past form of 「数える」, showing that it has already been counted. Note that the same kanji 「数」 is read differently in the noun and in the verb.","grammar:1666:ex3:words:0:zh":"he","grammar:1666:ex3:words:0:note":"かれ","grammar:1666:ex3:words:0:pos":"pronoun","grammar:1666:ex3:words:1:zh":"(topic)","grammar:1666:ex3:words:1:pos":"particle","grammar:1666:ex3:words:2:zh":"car","grammar:1666:ex3:words:2:note":"くるま","grammar:1666:ex3:words:2:pos":"noun","grammar:1666:ex3:words:3:zh":"(specifies what the number refers to)","grammar:1666:ex3:words:3:pos":"particle","grammar:1666:ex3:words:4:zh":"quantity","grammar:1666:ex3:words:4:note":"かず","grammar:1666:ex3:words:4:pos":"noun","grammar:1666:ex3:words:5:zh":"(object)","grammar:1666:ex3:words:5:pos":"particle","grammar:1666:ex3:words:6:zh":"to count","grammar:1666:ex3:words:6:note":"かぞえ","grammar:1666:ex3:words:6:pos":"verb","grammar:1666:ex3:words:7:zh":"(polite tone)","grammar:1666:ex3:words:7:pos":"auxiliary verb","grammar:1666:ex3:words:8:zh":"(past)","grammar:1666:ex3:words:8:pos":"auxiliary verb","grammar:1666:ex3:points:0":"「数える」 is a transitive verb, so what is counted is marked with 「を」.","grammar:1666:ex3:points:1":"As a noun 「数」 is read 「かず」, while 「数える」 is read 「かぞえる」.","grammar:1666:ex4:trans":"The children are counting things.","grammar:1666:ex4:structure":"〜を数えています","grammar:1666:ex4:words:0:zh":"children","grammar:1666:ex4:words:0:note":"こどもたち","grammar:1666:ex4:words:0:pos":"noun","grammar:1666:ex4:words:1:zh":"(topic)","grammar:1666:ex4:words:1:pos":"particle","grammar:1666:ex4:words:2:zh":"things","grammar:1666:ex4:words:2:note":"もの","grammar:1666:ex4:words:2:pos":"noun","grammar:1666:ex4:words:3:zh":"(object marker)","grammar:1666:ex4:words:3:pos":"particle","grammar:1666:ex4:words:4:zh":"counting","grammar:1666:ex4:words:4:note":"かぞえています","grammar:1666:ex4:words:4:pos":"verb","grammar:1666:ex4:points:0":"物を数える: to count things.","grammar:1666:ex4:points:1":"〜ている: ongoing action.","grammar:1666:ex5:trans":"During class, I raised my hand and counted.","grammar:1666:ex5:structure":"手を挙げて数えました","grammar:1666:ex5:words:0:zh":"during class","grammar:1666:ex5:words:0:note":"じゅぎょうちゅう","grammar:1666:ex5:words:0:pos":"noun","grammar:1666:ex5:words:1:zh":"(point in time)","grammar:1666:ex5:words:1:pos":"particle","grammar:1666:ex5:words:2:zh":"hand","grammar:1666:ex5:words:2:note":"て","grammar:1666:ex5:words:2:pos":"noun","grammar:1666:ex5:words:3:zh":"(object marker)","grammar:1666:ex5:words:3:pos":"particle","grammar:1666:ex5:words:4:zh":"raise","grammar:1666:ex5:words:4:note":"あげて","grammar:1666:ex5:words:4:pos":"verb","grammar:1666:ex5:words:5:zh":"counted","grammar:1666:ex5:words:5:note":"かぞえました","grammar:1666:ex5:words:5:pos":"verb","grammar:1666:ex5:points:0":"❗手を挙げる: to raise one's hand.","grammar:1666:ex5:points:1":"〜て: te-form linking (raise hand + count)."},"1667":{"example:1667:exzh":"He reported the crime.","example:1667:exzh2":"Emergency situations need to be reported.","example:1667:exzh3":"The police who received the report were dispatched.","example:1667:exzh4":"The details of a report must be accurate.","example:1667:exzh5":"I reported the accident."},"1668":{"example:1668:exzh":"There is a plan to blow up this bridge.","example:1668:exzh2":"I heard the sound of the explosion.","example:1668:exzh3":"You need to be careful during a blast.","example:1668:exzh4":"He is an explosives expert.","example:1668:exzh5":"An explosive device has been planted."},"1669":{"example:1669:exzh":"This information is confidential.","example:1669:exzh2":"Some data is treated as confidential.","example:1669:exzh3":"Keeping information confidential is required.","example:1669:exzh4":"You must not leak confidential information.","example:1669:exzh5":"His work is confidential."},"1670":{"example:1670:exzh":"He is a university student.","example:1670:exzh2":"The students are studying in the library.","example:1670:exzh3":"I am a student at a Japanese language school.","example:1670:exzh4":"That student is excellent.","example:1670:exzh5":"Student life is fun.","grammar:1670:ex:trans":"He is a university student.","grammar:1670:ex:structure":"〜の学生です","grammar:1670:ex:explain":"「大学の学生」 is joined with 「の」 and means a student at a university. 「は」 presents 「彼」 as the topic, and 「です」 politely asserts his identity. 「学生（がくせい）」 usually means a university or college student; elementary and junior high students are called 「児童」 or 「生徒」 instead, which is an easy point to mix up.","grammar:1670:ex:words:0:zh":"he","grammar:1670:ex:words:0:note":"かれ","grammar:1670:ex:words:0:pos":"pronoun","grammar:1670:ex:words:1:zh":"(topic)","grammar:1670:ex:words:1:pos":"particle","grammar:1670:ex:words:2:zh":"university","grammar:1670:ex:words:2:note":"だいがく","grammar:1670:ex:words:2:pos":"noun","grammar:1670:ex:words:3:zh":"'s","grammar:1670:ex:words:3:pos":"particle","grammar:1670:ex:words:4:zh":"student","grammar:1670:ex:words:4:note":"がくせい","grammar:1670:ex:words:4:pos":"noun","grammar:1670:ex:words:5:zh":"is","grammar:1670:ex:words:5:pos":"copula","grammar:1670:ex:points:0":"❗「学生（がくせい）」: student (usually a university or college student; elementary and junior high students are called 「児童」/「生徒」).","grammar:1670:ex:points:1":"学生: student","grammar:1670:ex2:trans":"The students are studying in the library.","grammar:1670:ex2:structure":"〜で勉強しています","grammar:1670:ex2:words:0:zh":"student","grammar:1670:ex2:words:0:note":"がくせい","grammar:1670:ex2:words:0:pos":"noun","grammar:1670:ex2:words:1:zh":"(topic)","grammar:1670:ex2:words:1:pos":"particle","grammar:1670:ex2:words:2:zh":"library","grammar:1670:ex2:words:2:note":"としょかん","grammar:1670:ex2:words:2:pos":"noun","grammar:1670:ex2:words:3:zh":"(place)","grammar:1670:ex2:words:3:pos":"particle","grammar:1670:ex2:words:4:zh":"has been studying","grammar:1670:ex2:words:4:note":"べんきょうしています","grammar:1670:ex2:words:4:pos":"verb","grammar:1670:ex2:points:0":"❗❓「図書館で」 = in the library (「で」 for place); 「学生」 = student.","grammar:1670:ex2:points:1":"「図書館で勉強」: studying in the library.","grammar:1670:ex3:trans":"I am a student at a Japanese language school.","grammar:1670:ex3:structure":"私 + は + 日本語学校 + の + 学生 + です","grammar:1670:ex3:words:0:zh":"I","grammar:1670:ex3:words:0:note":"わたし; first-person pronoun","grammar:1670:ex3:words:0:pos":"pronoun","grammar:1670:ex3:words:1:zh":"marks the topic","grammar:1670:ex3:words:1:pos":"particle","grammar:1670:ex3:words:2:zh":"Japanese","grammar:1670:ex3:words:2:note":"にほんご; the Japanese language","grammar:1670:ex3:words:2:pos":"noun","grammar:1670:ex3:words:3:zh":"school","grammar:1670:ex3:words:3:note":"がっこう; school","grammar:1670:ex3:words:3:pos":"noun","grammar:1670:ex3:words:4:zh":"'s","grammar:1670:ex3:words:4:pos":"particle","grammar:1670:ex3:words:5:zh":"student","grammar:1670:ex3:words:5:note":"がくせい; student","grammar:1670:ex3:words:5:pos":"noun","grammar:1670:ex3:words:6:zh":"is","grammar:1670:ex3:words:6:pos":"copula","grammar:1670:ex3:points:0":"「学生」 is read 「がくせい」 and means a person studying at a school.","grammar:1670:ex3:points:1":"「日本語学校の」 is joined with 「の」 to show which kind of school the student belongs to.","grammar:1670:ex3:points:2":"「です」 comes after a noun and politely states identity.","grammar:1670:ex4:trans":"That student is outstanding.","grammar:1670:ex4:structure":"〜は優秀です","grammar:1670:ex4:words:0:zh":"that","grammar:1670:ex4:words:0:pos":"pre-noun adjectival","grammar:1670:ex4:words:1:zh":"student","grammar:1670:ex4:words:1:note":"がくせい","grammar:1670:ex4:words:1:pos":"noun","grammar:1670:ex4:words:2:zh":"(topic)","grammar:1670:ex4:words:2:pos":"particle","grammar:1670:ex4:words:3:zh":"excellent","grammar:1670:ex4:words:3:note":"ゆうしゅう","grammar:1670:ex4:words:3:pos":"na-adjective","grammar:1670:ex4:words:4:zh":"(polite form)","grammar:1670:ex4:words:4:pos":"copula","grammar:1670:ex4:points:0":"❗「優秀な学生」: an excellent student; 「優秀」 = excellent.","grammar:1670:ex4:points:1":"優秀な学生: an excellent student.","grammar:1670:ex5:trans":"Student life is fun.","grammar:1670:ex5:structure":"〜は楽しいです","grammar:1670:ex5:words:0:zh":"student life","grammar:1670:ex5:words:0:note":"がくせいせいかつ","grammar:1670:ex5:words:0:pos":"noun","grammar:1670:ex5:words:1:zh":"(topic)","grammar:1670:ex5:words:1:pos":"particle","grammar:1670:ex5:words:2:zh":"interesting","grammar:1670:ex5:words:2:note":"たのしい","grammar:1670:ex5:words:2:pos":"adjective","grammar:1670:ex5:words:3:zh":"(polite form)","grammar:1670:ex5:words:3:pos":"copula","grammar:1670:ex5:points:0":"❗「学生生活」: student life (「学生」 + 「生活」).","grammar:1670:ex5:points:1":"「学生生活」: student life.","exam:1670:zh":"I'm a university student, and I take my teacher's class every day.","exam:1670:why":"「学生」 is a person who receives an education at a school. 「先生」 here means the person teaching, which is different from the role of receiving the lesson described in the sentence."},"1672":{"example:1672:exzh":"He works as a sergeant.","example:1672:exzh2":"The sergeant commands the unit.","example:1672:exzh3":"She is carrying out a sergeant's duties.","example:1672:exzh4":"Please report to the sergeant.","example:1672:exzh5":"The sergeant is in charge of training."},"1673":{"example:1673:exzh":"His identity has been confirmed.","example:1673:exzh2":"The identity needs to be made clear.","example:1673:exzh3":"An identity guarantor is required.","example:1673:exzh4":"An identity check has been carried out.","example:1673:exzh5":"This identity information is important."},"1674":{"example:1674:exzh":"Surviving under these circumstances is difficult.","example:1674:exzh2":"We confirmed their survival.","example:1674:exzh3":"The struggle for survival is becoming more intense.","example:1674:exzh4":"It is necessary to strive in order to survive.","example:1674:exzh5":"The environment affects survival."},"1675":{"example:1675:exzh":"I greeted him.","example:1675:exzh2":"Morning greetings are important.","example:1675:exzh3":"Don't forget to greet people.","example:1675:exzh4":"Returning a greeting is good manners.","example:1675:exzh5":"I greeted a friend.","grammar:1675:ex:trans":"I greeted him.","grammar:1675:ex:structure":"〜に挨拶をしました","grammar:1675:ex:explain":"「挨拶をする」 is a set expression: 「挨拶（あいさつ）」 is a noun, and adding 「を」 plus 「する」 gives to greet or to say hello. The 「に」 in 「彼に」 marks the person being greeted. The ending 「しました」 is the polite past form of 「する」. The whole sentence means I greeted him.","grammar:1675:ex:words:0:zh":"he","grammar:1675:ex:words:0:note":"かれ","grammar:1675:ex:words:0:pos":"pronoun","grammar:1675:ex:words:1:zh":"(object)","grammar:1675:ex:words:1:pos":"particle","grammar:1675:ex:words:2:zh":"greeting","grammar:1675:ex:words:2:note":"あいさつ","grammar:1675:ex:words:2:pos":"noun","grammar:1675:ex:words:3:zh":"(object marker)","grammar:1675:ex:words:3:pos":"particle","grammar:1675:ex:words:4:zh":"did","grammar:1675:ex:words:4:pos":"verb","grammar:1675:ex:points:0":"❗「挨拶（あいさつ）」: greeting, hello, a short speech; 「挨拶をする」 = to greet, to pay one's respects.","grammar:1675:ex:points:1":"挨拶をする: to greet someone.","grammar:1675:ex2:trans":"A morning greeting is important.","grammar:1675:ex2:structure":"〜の挨拶は大切です","grammar:1675:ex2:words:0:zh":"morning","grammar:1675:ex2:words:0:note":"あさ","grammar:1675:ex2:words:0:pos":"noun","grammar:1675:ex2:words:1:zh":"'s","grammar:1675:ex2:words:1:pos":"particle","grammar:1675:ex2:words:2:zh":"Greeting","grammar:1675:ex2:words:2:note":"あいさつ","grammar:1675:ex2:words:2:pos":"noun","grammar:1675:ex2:words:3:zh":"(topic)","grammar:1675:ex2:words:3:pos":"particle","grammar:1675:ex2:words:4:zh":"important","grammar:1675:ex2:words:4:note":"たいせつ","grammar:1675:ex2:words:4:pos":"na-adjective","grammar:1675:ex2:words:5:zh":"(polite form)","grammar:1675:ex2:words:5:pos":"copula","grammar:1675:ex2:points:0":"❗「朝の挨拶」: a morning greeting (like 「おはよう」); 「大切」 = important.","grammar:1675:ex2:points:1":"朝の挨拶: morning greeting.","grammar:1675:ex3:trans":"Please don't forget to say hello.","grammar:1675:ex3:structure":"Please don't forget to say hello.","grammar:1675:ex3:words:0:zh":"greeting","grammar:1675:ex3:words:0:note":"あいさつ","grammar:1675:ex3:words:0:pos":"noun","grammar:1675:ex3:words:1:zh":"(object marker)","grammar:1675:ex3:words:1:pos":"particle","grammar:1675:ex3:words:2:zh":"don't forget","grammar:1675:ex3:words:2:note":"わすれないで","grammar:1675:ex3:words:2:pos":"verb","grammar:1675:ex3:words:3:zh":"please","grammar:1675:ex3:words:3:pos":"auxiliary verb","grammar:1675:ex3:points:0":"❗挨拶を忘れる: to forget to greet; 〜ないで = don't ….","grammar:1675:ex3:points:1":"挨拶を忘れない: don't forget to greet.","grammar:1675:ex4:trans":"Greeting someone back is good manners.","grammar:1675:ex4:structure":"Greeting someone back is good manners.","grammar:1675:ex4:words:0:zh":"greeting","grammar:1675:ex4:words:0:note":"あいさつ","grammar:1675:ex4:words:0:pos":"noun","grammar:1675:ex4:words:1:zh":"(object marker)","grammar:1675:ex4:words:1:pos":"particle","grammar:1675:ex4:words:2:zh":"response","grammar:1675:ex4:words:2:note":"かえす","grammar:1675:ex4:words:2:pos":"verb","grammar:1675:ex4:words:3:zh":"(nominalizer)","grammar:1675:ex4:words:3:pos":"particle","grammar:1675:ex4:words:4:zh":"(topic)","grammar:1675:ex4:words:4:pos":"particle","grammar:1675:ex4:words:5:zh":"etiquette","grammar:1675:ex4:words:5:note":"れいぎ","grammar:1675:ex4:words:5:pos":"noun","grammar:1675:ex4:words:6:zh":"is","grammar:1675:ex4:words:6:pos":"copula","grammar:1675:ex4:points:0":"❗挨拶を返す: to return a greeting, to greet back; 礼儀 = manners, courtesy.","grammar:1675:ex4:points:1":"挨拶を返す: to return a greeting.","grammar:1675:ex5:trans":"I greeted a friend.","grammar:1675:ex5:structure":"〜に挨拶をしました","grammar:1675:ex5:words:0:zh":"friend","grammar:1675:ex5:words:0:note":"ともだち","grammar:1675:ex5:words:0:pos":"noun","grammar:1675:ex5:words:1:zh":"(object)","grammar:1675:ex5:words:1:pos":"particle","grammar:1675:ex5:words:2:zh":"greeting","grammar:1675:ex5:words:2:note":"あいさつ","grammar:1675:ex5:words:2:pos":"noun","grammar:1675:ex5:words:3:zh":"(object marker)","grammar:1675:ex5:words:3:pos":"particle","grammar:1675:ex5:words:4:zh":"did","grammar:1675:ex5:words:4:pos":"verb","grammar:1675:ex5:points:0":"❗友達に挨拶: to greet a friend.","grammar:1675:ex5:points:1":"友達に挨拶: to greet a friend."},"1676":{"example:1676:exzh":"Raising children is hard work.","example:1676:exzh2":"She is growing plants.","example:1676:exzh3":"I want to raise them in a good environment.","example:1676:exzh4":"I like raising dogs.","example:1676:exzh5":"I'm worried about how to raise them."},"1677":{"example:1677:exzh":"How customers are treated is important.","example:1677:exzh2":"Please be careful how you handle it.","example:1677:exzh3":"Please tell me how to handle this product.","example:1677:exzh4":"Please be careful when handling animals.","example:1677:exzh5":"He is a difficult person to deal with."},"1678":{"example:1678:exzh":"You need to stand by in an emergency.","example:1678:exzh2":"He is standing by.","example:1678:exzh3":"An alarm went off while on standby.","example:1678:exzh4":"We're ready to stand by.","example:1678:exzh5":"The police are always on standby."},"1679":{"example:1679:exzh":"I made it in time.","example:1679:exzh2":"We might not make it in time.","example:1679:exzh3":"If we leave a little earlier, we'll make it in time.","example:1679:exzh4":"Let's hurry so we make it in time.","example:1679:exzh5":"I caught the bus.","grammar:1679:ex:trans":"I made it on time.","grammar:1679:ex:structure":"〜に間に合った","grammar:1679:ex:explain":"「間に合う（まにあう）」 is an intransitive verb meaning to be in time or to make it; its target takes 「に」, so 「時間に間に合う」 = to be on time, to make it in time. The ending 「間に合った」 is the plain past form. It's an idiomatic compound verb whose literal sense of coming together in the middle extends to being in time.","grammar:1679:ex:words:0:zh":"time","grammar:1679:ex:words:0:note":"じかん","grammar:1679:ex:words:0:pos":"noun","grammar:1679:ex:words:1:zh":"(object)","grammar:1679:ex:words:1:pos":"particle","grammar:1679:ex:words:2:zh":"made it in time","grammar:1679:ex:words:2:note":"まにあった","grammar:1679:ex:words:2:pos":"verb","grammar:1679:ex:points:0":"❗間に合う（まにあう）: to be in time, to make it (intransitive verb); 〜に間に合う = to make it to…","grammar:1679:ex:points:1":"時間に間に合う: to be on time.","grammar:1679:ex2:trans":"It might be too late.","grammar:1679:ex2:structure":"間に合わないかもしれない","grammar:1679:ex2:words:0:zh":"not make it in time","grammar:1679:ex2:words:0:note":"まにあわない","grammar:1679:ex2:words:0:pos":"verb","grammar:1679:ex2:words:1:zh":"possible","grammar:1679:ex2:words:1:pos":"set phrase","grammar:1679:ex2:points:0":"❗間に合わない: to not make it in time (negative); 〜かもしれない = might…","grammar:1679:ex2:points:1":"かもしれない: maybe.","grammar:1679:ex3:trans":"If I leave a little earlier, I'll make it in time.","grammar:1679:ex3:structure":"〜出れば間に合う","grammar:1679:ex3:words:0:zh":"more","grammar:1679:ex3:words:0:pos":"adverb","grammar:1679:ex3:words:1:zh":"early","grammar:1679:ex3:words:1:note":"はやく","grammar:1679:ex3:words:1:pos":"adjective","grammar:1679:ex3:words:2:zh":"if I leave","grammar:1679:ex3:words:2:note":"でれば","grammar:1679:ex3:words:2:pos":"verb","grammar:1679:ex3:words:3:zh":"make it in time","grammar:1679:ex3:words:3:note":"まにあう","grammar:1679:ex3:words:3:pos":"verb","grammar:1679:ex3:points:0":"❗〜ば: if… (conditional ba-form); 早く出る = to leave early; 間に合う = to make it in time.","grammar:1679:ex3:points:1":"出れば間に合う: leave early and you'll make it.","grammar:1679:ex4:trans":"Let's hurry so we make it in time.","grammar:1679:ex4:structure":"間に合うように急ぎましょう","grammar:1679:ex4:words:0:zh":"make it in time","grammar:1679:ex4:words:0:note":"まにあう","grammar:1679:ex4:words:0:pos":"verb","grammar:1679:ex4:words:1:zh":"so as not to…","grammar:1679:ex4:words:1:pos":"auxiliary verb","grammar:1679:ex4:words:2:zh":"(made adverbial)","grammar:1679:ex4:words:2:pos":"particle","grammar:1679:ex4:words:3:zh":"let's hurry","grammar:1679:ex4:words:3:note":"いそぎましょう","grammar:1679:ex4:words:3:pos":"verb","grammar:1679:ex4:points:0":"❗〜ように: so that…, in order to…; 間に合うように = so as to make it in time; 急ぐ = to hurry.","grammar:1679:ex4:points:1":"間に合うように: so as to be in time.","grammar:1679:ex5:trans":"I made the bus.","grammar:1679:ex5:structure":"〜に間に合いました","grammar:1679:ex5:words:0:zh":"bus","grammar:1679:ex5:words:0:note":"loanword","grammar:1679:ex5:words:0:pos":"noun","grammar:1679:ex5:words:1:zh":"(object)","grammar:1679:ex5:words:1:pos":"particle","grammar:1679:ex5:words:2:zh":"made it in time","grammar:1679:ex5:words:2:note":"まにあいました","grammar:1679:ex5:words:2:pos":"verb","grammar:1679:ex5:points:0":"❗バスに間に合う: to catch the bus.","grammar:1679:ex5:points:1":"バスに間に合う: to make the bus."},"1680":{"example:1680:exzh":"I live in a small village.","example:1680:exzh2":"The village is quiet.","example:1680:exzh3":"That village has beautiful scenery.","example:1680:exzh4":"The people in the village are kind.","example:1680:exzh5":"There's a festival in the village.","grammar:1680:ex:trans":"I live in a small village.","grammar:1680:ex:structure":"〜に住んでいます","grammar:1680:ex:explain":"This sentence uses 「〜に住んでいます」 to say where someone lives, with 「に」 marking the place of residence, 「小さな村」. 「小さな」 is a pre-noun adjectival: it can only attach to a noun and cannot stand alone as a predicate (use the i-adjective 「小さい」 for that). 「住んでいます」 is the 「〜ている」 form of 「住む」, expressing the continuing state of living somewhere. 「村」 is read 「むら」.","grammar:1680:ex:words:0:zh":"small","grammar:1680:ex:words:0:note":"ちいさな","grammar:1680:ex:words:0:pos":"pre-noun adjectival","grammar:1680:ex:words:1:zh":"village","grammar:1680:ex:words:1:note":"むら","grammar:1680:ex:words:1:pos":"noun","grammar:1680:ex:words:2:zh":"(location of existence)","grammar:1680:ex:words:2:pos":"particle","grammar:1680:ex:words:3:zh":"live (there)","grammar:1680:ex:words:3:note":"すんでいます","grammar:1680:ex:words:3:pos":"verb","grammar:1680:ex:points:0":"❗村（むら）: village; 小さな村 = a small village.","grammar:1680:ex:points:1":"村: village.","grammar:1680:ex2:trans":"The village is quiet.","grammar:1680:ex2:structure":"The village is quiet.","grammar:1680:ex2:words:0:zh":"village","grammar:1680:ex2:words:0:note":"むら","grammar:1680:ex2:words:0:pos":"noun","grammar:1680:ex2:words:1:zh":"(topic)","grammar:1680:ex2:words:1:pos":"particle","grammar:1680:ex2:words:2:zh":"quiet","grammar:1680:ex2:words:2:note":"しずか","grammar:1680:ex2:words:2:pos":"na-adjective","grammar:1680:ex2:words:3:zh":"(polite form)","grammar:1680:ex2:words:3:pos":"copula","grammar:1680:ex2:points:0":"❗村が静か: the village is quiet; 静か = quiet.","grammar:1680:ex2:points:1":"村が静か: the village is quiet.","grammar:1680:ex3:trans":"That village has beautiful scenery.","grammar:1680:ex3:structure":"〜には〜があります (〜 has 〜)","grammar:1680:ex3:words:0:zh":"that","grammar:1680:ex3:words:0:pos":"pre-noun adjectival","grammar:1680:ex3:words:1:zh":"village","grammar:1680:ex3:words:1:note":"むら","grammar:1680:ex3:words:1:pos":"noun","grammar:1680:ex3:words:2:zh":"(location of existence)","grammar:1680:ex3:words:2:pos":"particle","grammar:1680:ex3:words:3:zh":"(contrast)","grammar:1680:ex3:words:3:pos":"particle","grammar:1680:ex3:words:4:zh":"beautiful","grammar:1680:ex3:words:4:note":"うつくしい","grammar:1680:ex3:words:4:pos":"adjective","grammar:1680:ex3:words:5:zh":"scenery","grammar:1680:ex3:words:5:note":"ふうけい","grammar:1680:ex3:words:5:pos":"noun","grammar:1680:ex3:words:6:zh":"(nominative)","grammar:1680:ex3:words:6:pos":"particle","grammar:1680:ex3:words:7:zh":"there is / are","grammar:1680:ex3:words:7:pos":"verb","grammar:1680:ex3:points:0":"❗美しい風景: beautiful scenery; 村にある = to be in the village.","grammar:1680:ex3:points:1":"村の風景: the village scenery.","grammar:1680:ex4:trans":"The people of the village are kind.","grammar:1680:ex4:structure":"〜の人々は親切です","grammar:1680:ex4:words:0:zh":"village","grammar:1680:ex4:words:0:note":"むら","grammar:1680:ex4:words:0:pos":"noun","grammar:1680:ex4:words:1:zh":"'s","grammar:1680:ex4:words:1:pos":"particle","grammar:1680:ex4:words:2:zh":"people","grammar:1680:ex4:words:2:note":"ひとびと","grammar:1680:ex4:words:2:pos":"noun","grammar:1680:ex4:words:3:zh":"(topic)","grammar:1680:ex4:words:3:pos":"particle","grammar:1680:ex4:words:4:zh":"kind","grammar:1680:ex4:words:4:note":"しんせつ","grammar:1680:ex4:words:4:pos":"na-adjective","grammar:1680:ex4:words:5:zh":"(polite form)","grammar:1680:ex4:words:5:pos":"copula","grammar:1680:ex4:points:0":"❗村の人々: the people of the village; 親切 = kind.","grammar:1680:ex4:points:1":"村の人々: the villagers.","grammar:1680:ex5:trans":"There's a festival in the village.","grammar:1680:ex5:structure":"村にお祭りがある","grammar:1680:ex5:words:0:zh":"village","grammar:1680:ex5:words:0:note":"むら","grammar:1680:ex5:words:0:pos":"noun","grammar:1680:ex5:words:1:zh":"(location of existence)","grammar:1680:ex5:words:1:pos":"particle","grammar:1680:ex5:words:2:zh":"festival","grammar:1680:ex5:words:2:note":"おまつり","grammar:1680:ex5:words:2:pos":"noun","grammar:1680:ex5:words:3:zh":"(nominative)","grammar:1680:ex5:words:3:pos":"particle","grammar:1680:ex5:words:4:zh":"there is / are","grammar:1680:ex5:words:4:pos":"verb","grammar:1680:ex5:points:0":"❗村にお祭りがある: there's a festival in the village; お祭り = festival.","grammar:1680:ex5:points:1":"村の祭り: the village festival."},"1681":{"example:1681:exzh":"There is a book on the table.","example:1681:exzh2":"Please clean the table.","example:1681:exzh3":"This table is expensive.","example:1681:exzh4":"There's a cat under the desk.","example:1681:exzh5":"I bought a new table.","grammar:1681:ex:trans":"There's a book on the table.","grammar:1681:ex:structure":"〜の上に〜があります","grammar:1681:ex:explain":"This sentence uses the basic existence pattern 「〜に〜があります」. In 「テーブルの上」, 「の」 marks position, 「に」 marks the place where something exists (on the table), 「が」 marks the thing that exists, 「本」, and 「あります」 expresses the existence of something inanimate. 「テーブル」 usually means a dining table or coffee table; a desk is usually called 「机（つくえ）」.","grammar:1681:ex:words:0:zh":"desk","grammar:1681:ex:words:0:note":"loanword","grammar:1681:ex:words:0:pos":"noun","grammar:1681:ex:words:1:zh":"'s","grammar:1681:ex:words:1:pos":"particle","grammar:1681:ex:words:2:zh":"on top of","grammar:1681:ex:words:2:note":"うえ","grammar:1681:ex:words:2:pos":"noun","grammar:1681:ex:words:3:zh":"(location of existence)","grammar:1681:ex:words:3:pos":"particle","grammar:1681:ex:words:4:zh":"book","grammar:1681:ex:words:4:note":"ほん","grammar:1681:ex:words:4:pos":"noun","grammar:1681:ex:words:5:zh":"(nominative)","grammar:1681:ex:words:5:pos":"particle","grammar:1681:ex:words:6:zh":"there is / are","grammar:1681:ex:words:6:pos":"verb","grammar:1681:ex:points:0":"❗テーブル: table (usually a dining table or coffee table; a desk is usually called 「机（つくえ）」).","grammar:1681:ex:points:1":"テーブル: table.","grammar:1681:ex2:trans":"Please clean the table.","grammar:1681:ex2:structure":"〜をきれいにしてください","grammar:1681:ex2:words:0:zh":"desk","grammar:1681:ex2:words:0:note":"loanword","grammar:1681:ex2:words:0:pos":"noun","grammar:1681:ex2:words:1:zh":"(object marker)","grammar:1681:ex2:words:1:pos":"particle","grammar:1681:ex2:words:2:zh":"clean","grammar:1681:ex2:words:2:pos":"na-adjective","grammar:1681:ex2:words:3:zh":"(result)","grammar:1681:ex2:words:3:pos":"particle","grammar:1681:ex2:words:4:zh":"do","grammar:1681:ex2:words:4:pos":"verb","grammar:1681:ex2:words:5:zh":"please","grammar:1681:ex2:words:5:pos":"auxiliary verb","grammar:1681:ex2:points:0":"❗〜をきれいにする: to make … clean; テーブル = table.","grammar:1681:ex2:points:1":"きれいにする: to clean up.","grammar:1681:ex3:trans":"This table is expensive.","grammar:1681:ex3:structure":"〜は高いです","grammar:1681:ex3:words:0:zh":"this","grammar:1681:ex3:words:0:pos":"pre-noun adjectival","grammar:1681:ex3:words:1:zh":"desk","grammar:1681:ex3:words:1:note":"loanword","grammar:1681:ex3:words:1:pos":"noun","grammar:1681:ex3:words:2:zh":"(topic)","grammar:1681:ex3:words:2:pos":"particle","grammar:1681:ex3:words:3:zh":"expensive","grammar:1681:ex3:words:3:note":"たかい","grammar:1681:ex3:words:3:pos":"adjective","grammar:1681:ex3:words:4:zh":"(polite form)","grammar:1681:ex3:words:4:pos":"copula","grammar:1681:ex3:points:0":"❗テーブルが高い: the table is expensive (高い = expensive, tall).","grammar:1681:ex3:points:1":"高いテーブル: an expensive table.","grammar:1681:ex4:trans":"There's a cat under the desk.","grammar:1681:ex4:structure":"〜の下に〜がいます","grammar:1681:ex4:words:0:zh":"desk","grammar:1681:ex4:words:0:note":"loanword","grammar:1681:ex4:words:0:pos":"noun","grammar:1681:ex4:words:1:zh":"'s","grammar:1681:ex4:words:1:pos":"particle","grammar:1681:ex4:words:2:zh":"under","grammar:1681:ex4:words:2:note":"した","grammar:1681:ex4:words:2:pos":"noun","grammar:1681:ex4:words:3:zh":"(location of existence)","grammar:1681:ex4:words:3:pos":"particle","grammar:1681:ex4:words:4:zh":"cat","grammar:1681:ex4:words:4:note":"ねこ","grammar:1681:ex4:words:4:pos":"noun","grammar:1681:ex4:words:5:zh":"(nominative)","grammar:1681:ex4:words:5:pos":"particle","grammar:1681:ex4:words:6:zh":"there is / are","grammar:1681:ex4:words:6:pos":"verb","grammar:1681:ex4:points:0":"❗テーブルの下: under the table; 猫がいる = there's a cat.","grammar:1681:ex4:points:1":"テーブルの下: under the table.","grammar:1681:ex5:trans":"I bought a new table.","grammar:1681:ex5:structure":"〜を買いました","grammar:1681:ex5:words:0:zh":"new","grammar:1681:ex5:words:0:note":"あたらしい","grammar:1681:ex5:words:0:pos":"adjective","grammar:1681:ex5:words:1:zh":"desk","grammar:1681:ex5:words:1:note":"loanword","grammar:1681:ex5:words:1:pos":"noun","grammar:1681:ex5:words:2:zh":"(object marker)","grammar:1681:ex5:words:2:pos":"particle","grammar:1681:ex5:words:3:zh":"bought","grammar:1681:ex5:words:3:note":"かいました","grammar:1681:ex5:words:3:pos":"verb","grammar:1681:ex5:points:0":"❗新しいテーブル: a new table.","grammar:1681:ex5:points:1":"テーブルを買う: to buy a table.","exam:1681:zh":"Before dinner, I set out plates and cups for four people on the table.","exam:1681:why":"「テーブル」 is a table for putting out food and eating at. 「本棚」 is for books, so it doesn't fit when you're getting dinner ready for four."},"1682":{"example:1682:exzh":"The police have a warrant.","example:1682:exzh2":"You can't search without a warrant.","example:1682:exzh3":"It takes time to get a warrant.","example:1682:exzh4":"I'll wait until the warrant is issued.","example:1682:exzh5":"It's necessary to apply for a warrant."},"1683":{"example:1683:exzh":"This act is illegal.","example:1683:exzh2":"Don't get involved in illegal transactions.","example:1683:exzh3":"He makes money illegally.","example:1683:exzh4":"Illegal acts are punished severely.","example:1683:exzh5":"This law is meant to prevent illegal acts."},"1685":{"example:1685:exzh":"This problem is simple.","example:1685:exzh2":"She has a simple way of thinking.","example:1685:exzh3":"Simple tasks are needed.","example:1685:exzh4":"This game is simple, but fun.","example:1685:exzh5":"I'll start with the simple problems."},"1687":{"example:1687:exzh":"Nuclear energy is important.","example:1687:exzh2":"There is an issue involving nuclear weapons.","example:1687:exzh3":"Nuclear development is still ongoing.","example:1687:exzh4":"We need to understand the power of nuclear energy.","example:1687:exzh5":"There is a debate about nuclear safety."},"1688":{"example:1688:exzh":"He is keeping his sanity.","example:1688:exzh2":"Losing your sanity is dangerous.","example:1688:exzh3":"There are times when you can't stay sane.","example:1688:exzh4":"She lost her sanity.","example:1688:exzh5":"It's important to stay sane."},"1690":{"example:1690:exzh":"He was captured as a hostage.","example:1690:exzh2":"A statement demanding the release of the hostages was issued.","example:1690:exzh3":"The police did everything they could to rescue the hostages.","example:1690:exzh4":"Several hostages are involved in this incident.","example:1690:exzh5":"I pray that the hostages are released safely."},"1691":{"example:1691:exzh":"This event had a major impact on us.","example:1691:exzh2":"I organized and recorded the events.","example:1691:exzh3":"I read the report about that event.","example:1691:exzh4":"Events often happen suddenly.","example:1691:exzh5":"Please tell me the details about the event."},"1692":{"example:1692:exzh":"I exchanged money into pounds.","example:1692:exzh2":"That item is twenty pounds.","example:1692:exzh3":"The pound's exchange rate is rising.","example:1692:exzh4":"I exchanged pounds for US dollars.","example:1692:exzh5":"You can send pounds online."},"1693":{"example:1693:exzh":"He is handling the problem carefully.","example:1693:exzh2":"I try to make decisions carefully.","example:1693:exzh3":"There are situations that require caution.","example:1693:exzh4":"A cautious approach brought success.","example:1693:exzh5":"She always acts cautiously."},"1694":{"example:1694:exzh":"The content of this book is very interesting.","example:1694:exzh2":"Please tell me what the meeting is about.","example:1694:exzh3":"It is important that the content is clear.","example:1694:exzh4":"I checked the content of the presentation.","example:1694:exzh5":"His lectures are rich in content."},"1695":{"example:1695:exzh":"This dish has a unique taste.","example:1695:exzh2":"I like spicy flavors.","example:1695:exzh3":"I added salt to adjust the flavor.","example:1695:exzh4":"I tried a new flavor of ice cream.","example:1695:exzh5":"This tea has a sweet taste.","grammar:1695:ex:trans":"This dish has a unique taste.","grammar:1695:ex:structure":"〜は独特な味がします","grammar:1695:ex:explain":"「味がする」 is a set expression: 「味（あじ）」 plus 「が」 and 「する」 means \"to taste of …,\" and this 「〜がする」 pattern is also used for other senses such as sounds and smells (音がする, 匂いがする). 「独特な」 is the na-adjective 「独特」 plus 「な」 modifying 「味」. 「は」 makes 「この料理」 the topic.","grammar:1695:ex:words:0:zh":"this","grammar:1695:ex:words:0:pos":"pre-noun adjectival","grammar:1695:ex:words:1:zh":"dish","grammar:1695:ex:words:1:note":"りょうり","grammar:1695:ex:words:1:pos":"noun","grammar:1695:ex:words:2:zh":"(topic)","grammar:1695:ex:words:2:pos":"particle","grammar:1695:ex:words:3:zh":"unique","grammar:1695:ex:words:3:note":"どくとく","grammar:1695:ex:words:3:pos":"na-adjective","grammar:1695:ex:words:4:zh":"(attributive form)","grammar:1695:ex:words:4:pos":"auxiliary verb","grammar:1695:ex:words:5:zh":"taste","grammar:1695:ex:words:5:note":"あじ","grammar:1695:ex:words:5:pos":"noun","grammar:1695:ex:words:6:zh":"(nominative)","grammar:1695:ex:words:6:pos":"particle","grammar:1695:ex:words:7:zh":"there is / are","grammar:1695:ex:words:7:pos":"verb","grammar:1695:ex:points:0":"❗味（あじ）: taste; 味がする = to taste of … (set expression).","grammar:1695:ex:points:1":"味がする: to have a taste.","grammar:1695:ex2:trans":"I like spicy flavors.","grammar:1695:ex2:structure":"〜が好きです","grammar:1695:ex2:words:0:zh":"I","grammar:1695:ex2:words:0:note":"わたし","grammar:1695:ex2:words:0:pos":"pronoun","grammar:1695:ex2:words:1:zh":"(topic)","grammar:1695:ex2:words:1:pos":"particle","grammar:1695:ex2:words:2:zh":"spicy","grammar:1695:ex2:words:2:note":"からい","grammar:1695:ex2:words:2:pos":"adjective","grammar:1695:ex2:words:3:zh":"taste","grammar:1695:ex2:words:3:note":"あじ","grammar:1695:ex2:words:3:pos":"noun","grammar:1695:ex2:words:4:zh":"(object)","grammar:1695:ex2:words:4:pos":"particle","grammar:1695:ex2:words:5:zh":"to like","grammar:1695:ex2:words:5:note":"すき","grammar:1695:ex2:words:5:pos":"na-adjective","grammar:1695:ex2:words:6:zh":"(polite form)","grammar:1695:ex2:words:6:pos":"copula","grammar:1695:ex2:points:0":"❗辛い味: a spicy taste; 味が好き = to like a flavor.","grammar:1695:ex2:points:1":"辛い味: a spicy taste.","grammar:1695:ex3:trans":"I added salt to adjust the taste.","grammar:1695:ex3:structure":"味を調整するために〜を入れました","grammar:1695:ex3:words:0:zh":"taste","grammar:1695:ex3:words:0:note":"あじ","grammar:1695:ex3:words:0:pos":"noun","grammar:1695:ex3:words:1:zh":"(object marker)","grammar:1695:ex3:words:1:pos":"particle","grammar:1695:ex3:words:2:zh":"to adjust, to regulate","grammar:1695:ex3:words:2:note":"ちょうせいする","grammar:1695:ex3:words:2:pos":"verb","grammar:1695:ex3:words:3:zh":"for the sake of","grammar:1695:ex3:words:3:pos":"noun","grammar:1695:ex3:words:4:zh":"(purpose)","grammar:1695:ex3:words:4:pos":"particle","grammar:1695:ex3:words:5:zh":"salt","grammar:1695:ex3:words:5:note":"しお","grammar:1695:ex3:words:5:pos":"noun","grammar:1695:ex3:words:6:zh":"(object marker)","grammar:1695:ex3:words:6:pos":"particle","grammar:1695:ex3:words:7:zh":"added","grammar:1695:ex3:words:7:note":"いれました","grammar:1695:ex3:words:7:pos":"verb","grammar:1695:ex3:points:0":"❗味を調整する: to adjust the flavor; 〜ために = in order to …","grammar:1695:ex3:points:1":"味を調整: adjusting the flavor.","grammar:1695:ex4:trans":"I tried a new flavor of ice cream.","grammar:1695:ex4:structure":"〜の〜を試しました","grammar:1695:ex4:words:0:zh":"new","grammar:1695:ex4:words:0:note":"あたらしい","grammar:1695:ex4:words:0:pos":"adjective","grammar:1695:ex4:words:1:zh":"flavor","grammar:1695:ex4:words:1:note":"あじ","grammar:1695:ex4:words:1:pos":"noun","grammar:1695:ex4:words:2:zh":"'s","grammar:1695:ex4:words:2:pos":"particle","grammar:1695:ex4:words:3:zh":"ice cream","grammar:1695:ex4:words:3:note":"loanword","grammar:1695:ex4:words:3:pos":"noun","grammar:1695:ex4:words:4:zh":"(object marker)","grammar:1695:ex4:words:4:pos":"particle","grammar:1695:ex4:words:5:zh":"tried","grammar:1695:ex4:words:5:note":"ためしました","grammar:1695:ex4:words:5:pos":"verb","grammar:1695:ex4:points:0":"❗新しい味: a new flavor; 試す = to try.","grammar:1695:ex4:points:1":"新しい味: a new flavor.","grammar:1695:ex5:trans":"This tea has a sweet taste.","grammar:1695:ex5:structure":"〜は甘い味がします","grammar:1695:ex5:words:0:zh":"this","grammar:1695:ex5:words:0:pos":"pre-noun adjectival","grammar:1695:ex5:words:1:zh":"tea","grammar:1695:ex5:words:1:note":"おちゃ","grammar:1695:ex5:words:1:pos":"noun","grammar:1695:ex5:words:2:zh":"(topic)","grammar:1695:ex5:words:2:pos":"particle","grammar:1695:ex5:words:3:zh":"sweet","grammar:1695:ex5:words:3:note":"あまい","grammar:1695:ex5:words:3:pos":"adjective","grammar:1695:ex5:words:4:zh":"taste","grammar:1695:ex5:words:4:note":"あじ","grammar:1695:ex5:words:4:pos":"noun","grammar:1695:ex5:words:5:zh":"(nominative)","grammar:1695:ex5:words:5:pos":"particle","grammar:1695:ex5:words:6:zh":"there is / are","grammar:1695:ex5:words:6:pos":"verb","grammar:1695:ex5:points:0":"❗甘い味がする: to taste sweet; 甘い = sweet.","grammar:1695:ex5:points:1":"甘い味がする: to taste sweet."},"1696":{"example:1696:exzh":"The government announced a new request.","example:1696:exzh2":"In response to the request, we held a discussion.","example:1696:exzh3":"This request is very significant.","example:1696:exzh4":"When you send a request, you need to follow the format.","example:1696:exzh5":"We responded quickly to his request."},"1697":{"example:1697:exzh":"At this shop, students make up thirty percent.","example:1697:exzh2":"I checked the terms for the twenty percent discount.","example:1697:exzh3":"Twenty percent of the whole group are foreigners.","example:1697:exzh4":"The chance that the plan will succeed is about fifty percent.","example:1697:exzh5":"This year's rice harvest was ten percent lower than last year's."},"1698":{"example:1698:exzh":"This order will be processed right away.","example:1698:exzh2":"I ordered a new book.","example:1698:exzh3":"I want to cancel the order.","example:1698:exzh4":"She ordered food.","example:1698:exzh5":"I received an order confirmation email.","grammar:1698:ex:trans":"This order will be processed right away.","grammar:1698:ex:structure":"〜はすぐに処理されます","grammar:1698:ex:explain":"This sentence uses the passive: 「処理されます」 is the passive form 「処理される」 of 「処理する」, meaning \"to be processed.\" The adverb 「すぐに」 (\"right away\") modifies the verb. 「は」 marks 「この注文」 as the topic. Japanese often uses the passive for objective statements when who performs the action is not emphasized. 「注文（ちゅうもん）」 means an order, a request to buy something.","grammar:1698:ex:words:0:zh":"this","grammar:1698:ex:words:0:pos":"pre-noun adjectival","grammar:1698:ex:words:1:zh":"order","grammar:1698:ex:words:1:note":"ちゅうもん","grammar:1698:ex:words:1:pos":"noun","grammar:1698:ex:words:2:zh":"(topic)","grammar:1698:ex:words:2:pos":"particle","grammar:1698:ex:words:3:zh":"immediately","grammar:1698:ex:words:3:pos":"adverb","grammar:1698:ex:words:4:zh":"is processed","grammar:1698:ex:words:4:note":"しょりされます","grammar:1698:ex:words:4:pos":"verb","grammar:1698:ex:points:0":"❗注文（ちゅうもん）: to order, to place an order; 注文を処理 = to process an order; 処理される = to be processed (passive form).","grammar:1698:ex:points:1":"注文: an order.","grammar:1698:ex2:trans":"I ordered a new book.","grammar:1698:ex2:structure":"〜を注文しました","grammar:1698:ex2:words:0:zh":"I","grammar:1698:ex2:words:0:note":"わたし","grammar:1698:ex2:words:0:pos":"pronoun","grammar:1698:ex2:words:1:zh":"(topic)","grammar:1698:ex2:words:1:pos":"particle","grammar:1698:ex2:words:2:zh":"new","grammar:1698:ex2:words:2:note":"あたらしい","grammar:1698:ex2:words:2:pos":"adjective","grammar:1698:ex2:words:3:zh":"book","grammar:1698:ex2:words:3:note":"ほん","grammar:1698:ex2:words:3:pos":"noun","grammar:1698:ex2:words:4:zh":"(object marker)","grammar:1698:ex2:words:4:pos":"particle","grammar:1698:ex2:words:5:zh":"ordered","grammar:1698:ex2:words:5:note":"ちゅうもんしました","grammar:1698:ex2:words:5:pos":"verb","grammar:1698:ex2:points:0":"❗注文する: to order, to place an order; 本を注文 = to order a book.","grammar:1698:ex2:points:1":"本を注文: ordering a book.","grammar:1698:ex3:trans":"I want to cancel the order.","grammar:1698:ex3:structure":"〜をキャンセルしたいです","grammar:1698:ex3:words:0:zh":"order","grammar:1698:ex3:words:0:note":"ちゅうもん","grammar:1698:ex3:words:0:pos":"noun","grammar:1698:ex3:words:1:zh":"(object marker)","grammar:1698:ex3:words:1:pos":"particle","grammar:1698:ex3:words:2:zh":"want to cancel","grammar:1698:ex3:words:2:pos":"verb","grammar:1698:ex3:words:3:zh":"(polite form)","grammar:1698:ex3:words:3:pos":"copula","grammar:1698:ex3:points:0":"❗注文をキャンセルする: to cancel an order; 〜たい = to want to …","grammar:1698:ex3:points:1":"注文をキャンセル: canceling an order.","grammar:1698:ex4:trans":"She ordered food.","grammar:1698:ex4:structure":"〜を注文しました","grammar:1698:ex4:words:0:zh":"she","grammar:1698:ex4:words:0:note":"かのじょ","grammar:1698:ex4:words:0:pos":"pronoun","grammar:1698:ex4:words:1:zh":"(topic)","grammar:1698:ex4:words:1:pos":"particle","grammar:1698:ex4:words:2:zh":"dish","grammar:1698:ex4:words:2:note":"りょうり","grammar:1698:ex4:words:2:pos":"noun","grammar:1698:ex4:words:3:zh":"(object marker)","grammar:1698:ex4:words:3:pos":"particle","grammar:1698:ex4:words:4:zh":"ordered","grammar:1698:ex4:words:4:note":"ちゅうもんしました","grammar:1698:ex4:words:4:pos":"verb","grammar:1698:ex4:points:0":"❗料理を注文する: to order food (at a restaurant).","grammar:1698:ex4:points:1":"料理を注文: ordering food.","grammar:1698:ex5:trans":"I received the order confirmation email.","grammar:1698:ex5:structure":"〜の確認メールが届きました","grammar:1698:ex5:words:0:zh":"order","grammar:1698:ex5:words:0:note":"ちゅうもん","grammar:1698:ex5:words:0:pos":"noun","grammar:1698:ex5:words:1:zh":"'s","grammar:1698:ex5:words:1:pos":"particle","grammar:1698:ex5:words:2:zh":"confirmation email","grammar:1698:ex5:words:2:note":"かくにんメール","grammar:1698:ex5:words:2:pos":"noun","grammar:1698:ex5:words:3:zh":"(nominative)","grammar:1698:ex5:words:3:pos":"particle","grammar:1698:ex5:words:4:zh":"was delivered","grammar:1698:ex5:words:4:note":"とどきました","grammar:1698:ex5:words:4:pos":"verb","grammar:1698:ex5:points:0":"❗確認メール: a confirmation email (確認 + mail); 届く = to arrive.","grammar:1698:ex5:points:1":"確認メール: a confirmation email."},"1699":{"example:1699:exzh":"He attempted to assassinate a famous politician.","example:1699:exzh2":"The movie is based on an assassination.","example:1699:exzh3":"Assassination is a dangerous act.","example:1699:exzh4":"Throughout history, many kings have been assassinated.","example:1699:exzh5":"He is suspected of being behind the assassination."}};